/* Public question bank: 48 scenario questions, 4 per module, trilingual (en/bn/fr). Answer index a is shared across languages. MINUKA and the Republic of Karana are fictional. Questions test rules, staff processes and judgement only, never collection technique. */
TRACK.qbank = [
 /* ---------- m1 FOUNDATIONS ---------- */
 {m:"m1", a:0,
  en:{q:"A battalion officer in the MINUKA Force asks why the Force needs its own MPKI when the mission already has a JMAC. What is the best reply?", o:["The Force needs its own picture to protect troops and plan operations, and shares it with the JMAC","It does not; the JMAC does all of it","To run national intelligence for each contingent","Because the JMAC is a purely civilian body that by policy may never receive or use any military reporting from the Force"], e:"MPKI supports the Force Commander’s planning, operations and force protection. It is part of the mission’s PKI system and shares with the JMAC and the MICM; it does not replace them or serve national aims."},
  bn:{q:"মিনুকা ফোর্সের একজন ব্যাটালিয়ন কর্মকর্তা জানতে চাইলেন, মিশনে JMAC থাকতে ফোর্সের নিজস্ব MPKI কেন দরকার। সবচেয়ে ভালো উত্তর কী?", o:["সৈন্যদের সুরক্ষা ও অপারেশন পরিকল্পনার জন্য ফোর্সের নিজস্ব চিত্র দরকার, যা JMAC-এর সঙ্গে ভাগ করা হয়","দরকার নেই; JMAC সবকিছু করে","প্রতিটি কন্টিনজেন্টের জাতীয় গোয়েন্দা কাজ চালানোর জন্য","কারণ JMAC সম্পূর্ণ বেসামরিক সংস্থা, যা নীতিগতভাবে ফোর্সের কোনো সামরিক প্রতিবেদন কখনো গ্রহণ বা ব্যবহার করতে পারে না এবং করবেও না"], e:"MPKI ফোর্স কমান্ডারের পরিকল্পনা, অপারেশন ও ফোর্স সুরক্ষায় সহায়তা করে। এটি মিশনের PKI ব্যবস্থার অংশ এবং JMAC ও MICM-এর সঙ্গে তথ্য ভাগ করে; এটি তাদের প্রতিস্থাপন করে না বা জাতীয় উদ্দেশ্যে কাজ করে না।"},
  fr:{q:"Un officier de bataillon de la Force de la MINUKA demande pourquoi la Force a besoin de son propre MPKI alors que la mission dispose déjà d’un JMAC. Quelle est la meilleure réponse ?", o:["La Force a besoin de sa propre image pour protéger les troupes et planifier, et la partage avec le JMAC","Elle n’en a pas besoin ; le JMAC fait tout","Pour mener le renseignement national de chaque contingent","Parce que le JMAC est un organe purement civil qui, par principe, ne peut jamais recevoir ni utiliser le moindre compte rendu militaire de la Force"], e:"Le MPKI appuie la planification, les opérations et la protection de la force du commandant. Il fait partie du système PKI de la mission et partage avec le JMAC et le MICM ; il ne les remplace pas et ne sert pas des fins nationales."}},
 {m:"m1", a:1,
  en:{q:"A new U2 staff officer asks which texts are the main military references under the 2019 PKI Policy, as of November 2026. What is accurate?", o:["The Brahimi Report and the HIPPO report","The MPKI Handbook (2025.10) and the PKISR Staff Handbook (2025.15); check for newer versions","Only the Infantry Battalion Manual","The national doctrine manuals of the largest troop-contributing countries, which the Force adopts in full and treats as UN policy"], e:"The 2019 Policy governs. The 2025 MPKI Handbook and PKISR Staff Handbook are the main military texts found; always check for a newer version."},
  bn:{q:"একজন নতুন U2 স্টাফ কর্মকর্তা জানতে চাইলেন, নভেম্বর ২০২৬ পর্যন্ত ২০১৯ PKI নীতির অধীনে প্রধান সামরিক রেফারেন্স কোনগুলো। সঠিক উত্তর কী?", o:["ব্রাহিমি প্রতিবেদন ও HIPPO প্রতিবেদন","MPKI হ্যান্ডবুক (2025.10) ও PKISR স্টাফ হ্যান্ডবুক (2025.15); নতুন সংস্করণ আছে কি না যাচাই করুন","কেবল পদাতিক ব্যাটালিয়ন ম্যানুয়াল","সবচেয়ে বড় সৈন্য প্রদানকারী দেশগুলোর জাতীয় ডকট্রিন ম্যানুয়াল, যা ফোর্স পুরোপুরি গ্রহণ করে এবং জাতিসংঘের নীতি হিসেবে গণ্য করে চলে"], e:"২০১৯ সালের নীতি প্রযোজ্য। ২০২৫ সালের MPKI হ্যান্ডবুক ও PKISR স্টাফ হ্যান্ডবুক পাওয়া প্রধান সামরিক দলিল; সবসময় নতুন সংস্করণ যাচাই করুন।"},
  fr:{q:"Un nouvel officier d’état-major du U2 demande quels textes sont les principales références militaires au titre de la Politique PKI de 2019, en novembre 2026. Quelle réponse est exacte ?", o:["Le rapport Brahimi et le rapport HIPPO","Le manuel MPKI (2025.10) et le manuel PKISR (2025.15) ; vérifier s’il existe des versions plus récentes","Seulement le manuel des bataillons d’infanterie","Les manuels de doctrine nationaux des principaux pays fournisseurs de contingents, que la Force adopte intégralement et traite comme politique de l’ONU"], e:"La Politique de 2019 fait foi. Les manuels MPKI et PKISR de 2025 sont les principaux textes militaires trouvés ; vérifiez toujours l’existence d’une version plus récente."}},
 {m:"m1", a:2,
  en:{q:"A Sector East G2 line reads: “Group X is likely to move south within 72 hours (B2).” How should this line be classed?", o:["Raw information","A request for information","An assessment: a PKI judgement","A confirmed fact that must be briefed as certain because the source is graded B and the information is rated 2"], e:"A judgement about what will happen, with estimative language and a grade, is an assessment. Raw information is a factual report not yet analysed. B2 means probably true, not confirmed."},
  bn:{q:"সেক্টর ইস্টের G2-এর একটি লাইনে লেখা: “গ্রুপ X সম্ভবত ৭২ ঘণ্টার মধ্যে দক্ষিণে সরবে (B2)।” এই লাইনকে কীভাবে শ্রেণিভুক্ত করবেন?", o:["কাঁচা তথ্য","তথ্যের অনুরোধ","একটি মূল্যায়ন: PKI বিচার","একটি নিশ্চিত সত্য, যা নিশ্চিত হিসেবেই ব্রিফ করতে হবে, কারণ উৎসের মান B এবং তথ্যের মান 2 দেওয়া হয়েছে"], e:"কী ঘটবে সে বিষয়ে প্রাক্কলনমূলক ভাষা ও মানসহ বিচার হলো মূল্যায়ন। কাঁচা তথ্য হলো বিশ্লেষণ-না-করা ঘটনার বিবরণ। B2 মানে সম্ভবত সত্য, নিশ্চিত নয়।"},
  fr:{q:"Une ligne du G2 du secteur Est indique : « Le groupe X se déplacera probablement vers le sud sous 72 heures (B2). » Comment classer cette ligne ?", o:["Une information brute","Une demande d’information","Une évaluation : un jugement PKI","Un fait confirmé à présenter comme certain, puisque la source est cotée B et l’information cotée 2"], e:"Un jugement sur ce qui va se produire, avec un langage estimatif et une cotation, est une évaluation. L’information brute est un compte rendu factuel non analysé. B2 signifie probablement vrai, non confirmé."}},
 {m:"m1", a:3,
  en:{q:"A MINUKA staff officer finds a handbook passage that seems to conflict with the 2019 PKI Policy. Which governs?", o:["The handbook, because it is newer","Whichever the contingent prefers","Neither; the officer should apply national doctrine until UNHQ issues a new consolidated text covering both","The Policy; raise the conflict and follow the mission SOP"], e:"The Policy governs and the handbooks implement it. Where texts disagree, say so plainly, raise it, and follow the mission’s own SOP."},
  bn:{q:"মিনুকার একজন স্টাফ কর্মকর্তা হ্যান্ডবুকের এমন একটি অংশ পেলেন যা ২০১৯ PKI নীতির সঙ্গে সাংঘর্ষিক মনে হয়। কোনটি প্রাধান্য পাবে?", o:["হ্যান্ডবুক, কারণ এটি নতুন","কন্টিনজেন্ট যেটি পছন্দ করে","কোনোটিই নয়; জাতিসংঘ সদর দপ্তর দুটিকে মিলিয়ে নতুন সমন্বিত দলিল না দেওয়া পর্যন্ত কর্মকর্তা জাতীয় ডকট্রিন প্রয়োগ করবেন","নীতি; বিরোধটি তুলে ধরুন এবং মিশনের SOP অনুসরণ করুন"], e:"নীতি প্রাধান্য পায়, হ্যান্ডবুক তা বাস্তবায়ন করে। দলিলগুলো না মিললে তা স্পষ্টভাবে বলুন, বিষয়টি তুলুন এবং মিশনের নিজস্ব SOP অনুসরণ করুন।"},
  fr:{q:"Un officier d’état-major de la MINUKA trouve un passage de manuel qui semble contredire la Politique PKI de 2019. Lequel prévaut ?", o:["Le manuel, parce qu’il est plus récent","Celui que préfère le contingent","Aucun ; l’officier applique la doctrine nationale jusqu’à ce que le Siège publie un nouveau texte consolidé couvrant les deux","La Politique ; signaler le conflit et suivre la SOP de la mission"], e:"La Politique fait foi et les manuels la mettent en œuvre. Quand les textes divergent, dites-le clairement, signalez-le et suivez la SOP propre à la mission."}},
 /* ---------- m2 RULES ---------- */
 {m:"m2", a:0,
  en:{q:"During a MINUKA patrol in Sector North, a villager offers information about an armed group in return for money. What should the patrol leader do?", o:["Make no payment or promise; report the offer to the S2 and follow the SOP","Pay a small amount from the patrol fund","Promise payment later to keep the contact","Agree to meet again at night away from the base so that the villager is not seen with peacekeepers by the armed group"], e:"Paying or handling sources is outside a patrol’s role and outside this course. Stop, record the offer factually and refer it up the chain; risks to the villager must also be considered."},
  bn:{q:"সেক্টর নর্থে মিনুকার একটি টহলের সময় একজন গ্রামবাসী টাকার বিনিময়ে একটি সশস্ত্র গোষ্ঠী সম্পর্কে তথ্য দিতে চাইলেন। টহল নেতা কী করবেন?", o:["কোনো অর্থ বা প্রতিশ্রুতি নয়; প্রস্তাবটি S2-কে জানান এবং SOP অনুসরণ করুন","টহল তহবিল থেকে অল্প টাকা দিন","যোগাযোগ রাখতে পরে টাকা দেওয়ার প্রতিশ্রুতি দিন","ঘাঁটি থেকে দূরে রাতে আবার দেখা করতে রাজি হোন, যাতে সশস্ত্র গোষ্ঠী গ্রামবাসীকে শান্তিরক্ষীদের সঙ্গে দেখতে না পায় এবং সন্দেহ না করে"], e:"উৎসকে অর্থ দেওয়া বা পরিচালনা করা টহলের ভূমিকার বাইরে এবং এই কোর্সের বাইরে। থামুন, প্রস্তাবটি তথ্যভিত্তিকভাবে লিখে রাখুন এবং চেইন অব কমান্ডে জানান; গ্রামবাসীর ঝুঁকিও বিবেচনা করতে হবে।"},
  fr:{q:"Pendant une patrouille de la MINUKA dans le secteur Nord, un villageois propose des informations sur un groupe armé contre de l’argent. Que doit faire le chef de patrouille ?", o:["Ni paiement ni promesse ; signaler l’offre au S2 et suivre la SOP","Payer une petite somme sur le fonds de la patrouille","Promettre un paiement plus tard pour garder le contact","Accepter de le revoir la nuit loin de la base pour que le groupe armé ne voie pas le villageois avec des Casques bleus"], e:"Payer ou gérer des sources ne relève pas d’une patrouille ni de ce cours. Arrêtez, consignez l’offre de façon factuelle et transmettez-la à la chaîne de commandement ; les risques pour le villageois doivent aussi être pris en compte."}},
 {m:"m2", a:1,
  en:{q:"A contingent officer in MINUKA Force HQ wants to e-mail the latest Force INTSUM to his national capital. What is the rule?", o:["Allowed if it helps his country plan","Not without authorization; UN PKI is shared only under mission rules","Allowed once it is marked unclassified","Allowed because every troop-contributing country owns all reporting produced by its own officers while serving in the Force"], e:"PKI produced in the mission is UN information, shared only as the mission’s sharing arrangements allow. National channels are separate and must not receive UN products without authorization."},
  bn:{q:"মিনুকা ফোর্স সদর দপ্তরের একজন কন্টিনজেন্ট কর্মকর্তা সর্বশেষ ফোর্স INTSUM নিজ দেশের রাজধানীতে ইমেইল করতে চান। নিয়ম কী?", o:["তাঁর দেশের পরিকল্পনায় সাহায্য করলে অনুমোদিত","অনুমোদন ছাড়া নয়; জাতিসংঘের PKI কেবল মিশনের নিয়মে ভাগ করা হয়","অশ্রেণিভুক্ত চিহ্ন দিলে অনুমোদিত","অনুমোদিত, কারণ ফোর্সে দায়িত্ব পালনকালে প্রতিটি সৈন্য প্রদানকারী দেশ তার নিজস্ব কর্মকর্তাদের তৈরি সব প্রতিবেদনের মালিক হিসেবে গণ্য হয়"], e:"মিশনে তৈরি PKI জাতিসংঘের তথ্য, যা কেবল মিশনের বিনিময় ব্যবস্থা অনুযায়ী ভাগ করা যায়। জাতীয় চ্যানেল আলাদা এবং অনুমোদন ছাড়া জাতিসংঘের পণ্য পেতে পারে না।"},
  fr:{q:"Un officier de contingent au QG de la Force de la MINUKA veut envoyer la dernière INTSUM de la Force à sa capitale par courriel. Quelle est la règle ?", o:["Autorisé si cela aide son pays à planifier","Pas sans autorisation ; le PKI de l’ONU ne se partage que selon les règles de la mission","Autorisé une fois marqué non classifié","Autorisé, car chaque pays fournisseur de contingents possède tous les comptes rendus produits par ses officiers pendant leur service dans la Force"], e:"Le PKI produit dans la mission est une information de l’ONU, partagée seulement selon les arrangements de partage de la mission. Les canaux nationaux sont distincts et ne reçoivent pas de produits de l’ONU sans autorisation."}},
 {m:"m2", a:2,
  en:{q:"Which activity by a MINUKA patrol stays within the non-clandestine rule?", o:["Wearing civilian clothes to blend in at a market","Hiding a camera in a vehicle","Openly observing and talking with people while in uniform","Asking a local trader to report secretly on his neighbours each week in exchange for food from the company stores"], e:"PKI is non-clandestine. Open observation and positive, overt interaction with the population are normal patrol activity. Disguise, concealment and secret tasking of civilians are not."},
  bn:{q:"মিনুকার একটি টহলের কোন কাজটি অ-গোপনীয়তার নিয়মের মধ্যে থাকে?", o:["বাজারে মিশে যেতে বেসামরিক পোশাক পরা","গাড়িতে ক্যামেরা লুকিয়ে রাখা","ইউনিফর্ম পরে প্রকাশ্যে পর্যবেক্ষণ ও মানুষের সঙ্গে কথা বলা","কোম্পানির ভাণ্ডার থেকে খাবারের বিনিময়ে একজন স্থানীয় ব্যবসায়ীকে প্রতি সপ্তাহে গোপনে তাঁর প্রতিবেশীদের সম্পর্কে জানাতে বলা"], e:"PKI অ-গোপন। প্রকাশ্য পর্যবেক্ষণ এবং জনগণের সঙ্গে ইতিবাচক, প্রকাশ্য যোগাযোগ টহলের স্বাভাবিক কাজ। ছদ্মবেশ, লুকানো এবং বেসামরিক মানুষকে গোপনে কাজ দেওয়া নয়।"},
  fr:{q:"Quelle activité d’une patrouille de la MINUKA reste conforme à la règle de non-clandestinité ?", o:["Porter une tenue civile pour se fondre dans un marché","Cacher une caméra dans un véhicule","Observer ouvertement et parler avec la population en uniforme","Demander à un commerçant local de rendre compte en secret de ses voisins chaque semaine contre des vivres des magasins de la compagnie"], e:"Le PKI est non clandestin. L’observation ouverte et une interaction positive et visible avec la population sont des activités normales de patrouille. Le déguisement, la dissimulation et les tâches secrètes confiées à des civils ne le sont pas."}},
 {m:"m2", a:3,
  en:{q:"A host-State officer offers a MINUKA battalion S2 detainee statements in exchange for Force patrol schedules. What should the S2 do?", o:["Accept; the statements may save lives","Accept the statements but refuse the schedules","Accept both, but grade the statements F6 and keep the exchange off the record so that no rule is formally engaged","Decline; refer it to the chain of command and seek HRDDP advice"], e:"Patrol schedules are protected operational information, and detainee statements may be obtained by torture or ill-treatment. Decline, record it and refer it; HRDDP and the sharing rules apply."},
  bn:{q:"একজন আয়োজক রাষ্ট্রের কর্মকর্তা মিনুকার একজন ব্যাটালিয়ন S2-কে ফোর্সের টহলসূচির বিনিময়ে বন্দিদের জবানবন্দি দিতে চাইলেন। S2 কী করবেন?", o:["গ্রহণ করুন; জবানবন্দি জীবন বাঁচাতে পারে","জবানবন্দি নিন কিন্তু টহলসূচি দেবেন না","দুটোই গ্রহণ করুন, তবে জবানবন্দির মান F6 দিন এবং বিনিময়টি নথির বাইরে রাখুন, যাতে আনুষ্ঠানিকভাবে কোনো নিয়ম প্রযোজ্য না হয়","প্রত্যাখ্যান করুন; চেইন অব কমান্ডে জানান এবং HRDDP পরামর্শ নিন"], e:"টহলসূচি সুরক্ষিত অপারেশনাল তথ্য, আর বন্দিদের জবানবন্দি নির্যাতন বা দুর্ব্যবহারের মাধ্যমে নেওয়া হতে পারে। প্রত্যাখ্যান করুন, লিখে রাখুন এবং জানান; HRDDP ও বিনিময়ের নিয়ম প্রযোজ্য।"},
  fr:{q:"Un officier de l’État hôte propose à un S2 de bataillon de la MINUKA des déclarations de détenus en échange des horaires de patrouille de la Force. Que doit faire le S2 ?", o:["Accepter ; les déclarations peuvent sauver des vies","Accepter les déclarations mais refuser les horaires","Accepter les deux, mais coter les déclarations F6 et garder l’échange hors registre pour qu’aucune règle ne soit formellement engagée","Refuser ; en référer à la chaîne de commandement et demander un avis HRDDP"], e:"Les horaires de patrouille sont des informations opérationnelles protégées, et les déclarations de détenus peuvent avoir été obtenues par la torture ou des mauvais traitements. Refusez, consignez et transmettez ; la HRDDP et les règles de partage s’appliquent."}},
 /* ---------- m3 FORCE ---------- */
 {m:"m3", a:0,
  en:{q:"In the MINUKA Force, who leads and directs all MPKI in the mission and represents the Force Commander at the MICM?", o:["The Chief U2","The battalion S2","The Chief JMAC","The senior intelligence officer of the largest troop-contributing country, chosen by agreement among the contingents"], e:"The MPKI Handbook gives the U2 the lead over all MPKI in the mission, including battle rhythm, SOPs and scarce capabilities, and the U2 represents the Force Commander at the MICM."},
  bn:{q:"মিনুকা ফোর্সে কে মিশনের সব MPKI পরিচালনা ও নির্দেশনা দেন এবং MICM-এ ফোর্স কমান্ডারের প্রতিনিধিত্ব করেন?", o:["চিফ U2","ব্যাটালিয়ন S2","চিফ JMAC","কন্টিনজেন্টগুলোর পারস্পরিক সম্মতিতে বেছে নেওয়া সবচেয়ে বড় সৈন্য প্রদানকারী দেশের জ্যেষ্ঠ গোয়েন্দা কর্মকর্তা"], e:"MPKI হ্যান্ডবুক অনুযায়ী U2 মিশনের সব MPKI-এর নেতৃত্ব দেয়, যার মধ্যে ব্যাটল রিদম, SOP ও দুর্লভ সক্ষমতা বণ্টন আছে, এবং MICM-এ ফোর্স কমান্ডারের প্রতিনিধিত্ব করে।"},
  fr:{q:"Dans la Force de la MINUKA, qui dirige l’ensemble du MPKI de la mission et représente le commandant de la force au MICM ?", o:["Le chef U2","Le S2 de bataillon","Le chef du JMAC","L’officier de renseignement le plus ancien du principal pays fournisseur de contingents, désigné d’un commun accord entre contingents"], e:"Le manuel MPKI confie au U2 la direction de tout le MPKI de la mission, y compris le rythme de bataille, les SOP et les capacités rares, et le U2 représente le commandant de la force au MICM."}},
 {m:"m3", a:1,
  en:{q:"A MINUKA company will operate alone at a remote site in Sector East for six weeks. What MPKI support does the MPKI Handbook suggest?", o:["None; the battalion S2 covers it remotely","A COIST of two persons trained in MPKI","A full G2 branch","A PKISR unit permanently assigned to the company commander with its own tasking authority and its own analysts"], e:"A Company PKI Support Team (COIST) of two trained persons, robust for austere conditions, supports remote or task-specific companies."},
  bn:{q:"মিনুকার একটি কোম্পানি সেক্টর ইস্টের একটি দূরবর্তী স্থানে ছয় সপ্তাহ একা কাজ করবে। MPKI হ্যান্ডবুক কোন MPKI সহায়তার পরামর্শ দেয়?", o:["কিছুই না; ব্যাটালিয়ন S2 দূর থেকে দেখবে","MPKI-তে প্রশিক্ষিত দুজনের একটি COIST","একটি পূর্ণ G2 শাখা","কোম্পানি কমান্ডারের অধীনে স্থায়ীভাবে নিযুক্ত একটি PKISR ইউনিট, যার নিজস্ব টাস্কিং কর্তৃত্ব ও নিজস্ব বিশ্লেষক থাকবে"], e:"দূরবর্তী বা বিশেষ কাজে নিয়োজিত কোম্পানিকে সহায়তা দেয় দুজন প্রশিক্ষিত সদস্যের কোম্পানি PKI সহায়তা দল (COIST), যা কঠিন পরিবেশে টিকে থাকার উপযোগী।"},
  fr:{q:"Une compagnie de la MINUKA opérera seule sur un site isolé du secteur Est pendant six semaines. Quel appui MPKI le manuel MPKI suggère-t-il ?", o:["Aucun ; le S2 du bataillon s’en charge à distance","Une COIST de deux personnes formées au MPKI","Une branche G2 complète","Une unité PKISR affectée en permanence au commandant de compagnie, avec sa propre autorité de tâche et ses propres analystes"], e:"Une équipe d’appui PKI de compagnie (COIST) de deux personnes formées, adaptée aux conditions austères, appuie les compagnies isolées ou à tâche particulière."}},
 {m:"m3", a:2,
  en:{q:"What does the MINUKA military component routinely send to the Joint Operations Centre?", o:["Only threat-to-life reports","Its source register","All daily situation reports","Nothing, because the JOC is a police body and military reporting goes only to the Force Commander’s personal staff"], e:"The MPKI Handbook says the military component sends all daily situation reports to the JOC routinely; sharing principles are set in the MISP."},
  bn:{q:"মিনুকার সামরিক অংশ নিয়মিতভাবে যৌথ অপারেশন কেন্দ্রে কী পাঠায়?", o:["কেবল জীবনের ঝুঁকি-সংক্রান্ত প্রতিবেদন","এর উৎস রেজিস্টার","সব দৈনিক পরিস্থিতি প্রতিবেদন","কিছুই না, কারণ JOC একটি পুলিশ সংস্থা এবং সামরিক প্রতিবেদন কেবল ফোর্স কমান্ডারের ব্যক্তিগত স্টাফের কাছেই যায়"], e:"MPKI হ্যান্ডবুক অনুযায়ী সামরিক অংশ নিয়মিতভাবে সব দৈনিক পরিস্থিতি প্রতিবেদন JOC-তে পাঠায়; বিনিময়ের নীতি MISP-এ নির্ধারিত।"},
  fr:{q:"Qu’envoie systématiquement la composante militaire de la MINUKA au Centre d’opérations conjoint ?", o:["Seulement les comptes rendus de menace pour la vie","Son registre des sources","Tous les rapports de situation quotidiens","Rien, car le JOC est un organe de police et les comptes rendus militaires vont seulement à l’état-major particulier du commandant"], e:"Selon le manuel MPKI, la composante militaire envoie systématiquement tous ses rapports de situation quotidiens au JOC ; les principes de partage sont fixés dans le MISP."}},
 {m:"m3", a:3,
  en:{q:"MINUKA is setting up a Peacekeeping-Intelligence Management Board. Under the PKISR Staff Handbook, who chairs it at minimum?", o:["The SRSG in every mission","The Director of Mission Support","A rotating chair drawn each month from the contingent that flew the most PKISR hours in the previous month","The Chief U2"], e:"The Chief PKISR organises the PKIMB and it is chaired at minimum by the Chief U2; leadership may chair in large missions. JMAC, UNPOL and U6 are encouraged to attend."},
  bn:{q:"মিনুকা একটি শান্তিরক্ষা-গোয়েন্দা তথ্য ব্যবস্থাপনা বোর্ড গঠন করছে। PKISR স্টাফ হ্যান্ডবুক অনুযায়ী ন্যূনতম পর্যায়ে কে এর সভাপতিত্ব করেন?", o:["প্রতিটি মিশনে SRSG","মিশন সাপোর্টের পরিচালক","প্রতি মাসে আবর্তনক্রমে সেই কন্টিনজেন্ট থেকে সভাপতি, যারা আগের মাসে সবচেয়ে বেশি PKISR ঘণ্টা উড্ডয়ন করেছে","চিফ U2"], e:"চিফ PKISR বোর্ডের আয়োজন করেন এবং ন্যূনতম পর্যায়ে চিফ U2 সভাপতিত্ব করেন; বড় মিশনে নেতৃত্ব পর্যায় সভাপতিত্ব করতে পারে। JMAC, UNPOL ও U6-কে অংশ নিতে উৎসাহিত করা হয়।"},
  fr:{q:"La MINUKA met en place un conseil de gestion du renseignement. Selon le manuel PKISR, qui le préside au minimum ?", o:["Le RSSG dans chaque mission","Le directeur de l’appui à la mission","Une présidence tournante confiée chaque mois au contingent ayant effectué le plus d’heures de vol PKISR le mois précédent","Le chef U2"], e:"Le chef PKISR organise le PKIMB, présidé au minimum par le chef U2 ; la direction peut présider dans les grandes missions. Le JMAC, UNPOL et le U6 sont encouragés à y participer."}},
 /* ---------- m4 REQUIREMENTS ---------- */
 {m:"m4", a:0,
  en:{q:"Which requirement is best written for a MINUKA checkpoint patrol on the Weru road?", o:["What weapons do members of Group X carry at the Weru road checkpoint between 0600 and 1800?","What are the threats to PoC?","Report everything unusual","Find out the general intentions, capabilities and alliances of every armed actor across Sector East and report them whenever possible"], e:"Good requirements are specific, answerable by the asset and time-bound. Broad PIRs are broken down into questions a patrol can actually answer."},
  bn:{q:"ওয়েরু সড়কে মিনুকার একটি চেকপয়েন্ট টহলের জন্য কোন চাহিদাটি সবচেয়ে ভালোভাবে লেখা?", o:["০৬০০ থেকে ১৮০০-র মধ্যে ওয়েরু সড়কের চেকপয়েন্টে গ্রুপ X-এর সদস্যরা কী অস্ত্র বহন করে?","PoC-এর জন্য হুমকি কী কী?","অস্বাভাবিক সবকিছু জানান","সেক্টর ইস্ট জুড়ে প্রতিটি সশস্ত্র পক্ষের সাধারণ উদ্দেশ্য, সক্ষমতা ও জোট খুঁজে বের করুন এবং যখনই সম্ভব হয় সেগুলো সম্পর্কে বিস্তারিত প্রতিবেদন দিন"], e:"ভালো চাহিদা নির্দিষ্ট, সম্পদের পক্ষে উত্তরযোগ্য এবং সময়সীমাবদ্ধ। বিস্তৃত PIR ভেঙে এমন প্রশ্নে পরিণত করা হয় যার উত্তর টহল আসলে দিতে পারে।"},
  fr:{q:"Quel besoin est le mieux rédigé pour une patrouille de la MINUKA à un point de contrôle de la route de Weru ?", o:["Quelles armes portent les membres du groupe X au point de contrôle de la route de Weru entre 6 h et 18 h ?","Quelles sont les menaces pour la PoC ?","Signaler tout ce qui est inhabituel","Déterminer les intentions générales, capacités et alliances de tous les acteurs armés du secteur Est et en rendre compte chaque fois que possible"], e:"Un bon besoin est précis, accessible au moyen et borné dans le temps. Les PIR larges sont décomposés en questions auxquelles une patrouille peut réellement répondre."}},
 {m:"m4", a:1,
  en:{q:"A line in the MINUKA Force IAP shows NLT 1200 and LTIOV 1800 for one EEI. What does the gap between them provide?", o:["Rest time for the patrol","Time for analysts to work before the answer loses value","A margin for late tasking","Nothing, because NLT and LTIOV are two names used by different handbooks for exactly the same deadline"], e:"The PKISR Staff Handbook explains that the gap between NLT and LTIOV is analyst time. Note that LTIOV is expanded differently in the handbooks; follow the mission SOP."},
  bn:{q:"মিনুকা ফোর্স IAP-এর একটি লাইনে একটি EEI-এর জন্য NLT ১২০০ এবং LTIOV ১৮০০ দেখানো আছে। দুটির মধ্যবর্তী ব্যবধান কী দেয়?", o:["টহলের বিশ্রামের সময়","উত্তরের মূল্য হারানোর আগে বিশ্লেষকদের কাজের সময়","দেরিতে টাস্কিংয়ের অবকাশ","কিছুই না, কারণ NLT ও LTIOV হলো বিভিন্ন হ্যান্ডবুকে একই সময়সীমার জন্য ব্যবহৃত দুটি ভিন্ন নাম মাত্র"], e:"PKISR স্টাফ হ্যান্ডবুক ব্যাখ্যা করে যে NLT ও LTIOV-এর ব্যবধান হলো বিশ্লেষকের সময়। লক্ষ করুন, হ্যান্ডবুকগুলোতে LTIOV-এর পূর্ণরূপ ভিন্ন; মিশনের SOP অনুসরণ করুন।"},
  fr:{q:"Une ligne de l’IAP de la Force de la MINUKA indique NLT 1200 et LTIOV 1800 pour un EEI. Que procure l’écart entre les deux ?", o:["Du repos pour la patrouille","Du temps d’analyse avant que la réponse perde sa valeur","Une marge pour une tâche tardive","Rien, car NLT et LTIOV sont deux noms employés par des manuels différents pour exactement la même échéance"], e:"Le manuel PKISR explique que l’écart entre NLT et LTIOV correspond au temps des analystes. Le développement de LTIOV diffère selon les manuels ; suivez la SOP de la mission."}},
 {m:"m4", a:2,
  en:{q:"A MINUKA instructor asks the class to put the requirements chain in order, from broadest to most specific. Which order is right?", o:["EEI, SIR, PIR, CCIR","PIR, CCIR, EEI, SIR","CCIR, PIR, SIR, EEI","There is no fixed order; each battalion designs its own chain without any reference to Force requirements"], e:"CCIRs lead to PIRs, which are broken into SIRs and then EEIs, the final questions given to assets. Each level stays coherent with the level above."},
  bn:{q:"মিনুকার একজন প্রশিক্ষক ক্লাসকে চাহিদার শৃঙ্খল সবচেয়ে বিস্তৃত থেকে সবচেয়ে নির্দিষ্ট ক্রমে সাজাতে বললেন। কোন ক্রমটি সঠিক?", o:["EEI, SIR, PIR, CCIR","PIR, CCIR, EEI, SIR","CCIR, PIR, SIR, EEI","কোনো নির্দিষ্ট ক্রম নেই; প্রতিটি ব্যাটালিয়ন ফোর্সের চাহিদার কোনো উল্লেখ ছাড়াই নিজের মতো শৃঙ্খল তৈরি করে"], e:"CCIR থেকে PIR আসে, যা SIR এবং তারপর EEI-তে ভাঙা হয়; EEI হলো সম্পদকে দেওয়া চূড়ান্ত প্রশ্ন। প্রতিটি স্তর ওপরের স্তরের সঙ্গে সামঞ্জস্যপূর্ণ থাকে।"},
  fr:{q:"Un formateur de la MINUKA demande de classer la chaîne des besoins du plus large au plus précis. Quel ordre est juste ?", o:["EEI, SIR, PIR, CCIR","PIR, CCIR, EEI, SIR","CCIR, PIR, SIR, EEI","Il n’y a pas d’ordre fixe ; chaque bataillon conçoit sa propre chaîne sans aucune référence aux besoins de la Force"], e:"Les CCIR conduisent aux PIR, décomposés en SIR puis en EEI, questions finales confiées aux moyens. Chaque niveau reste cohérent avec le niveau supérieur."}},
 {m:"m4", a:3,
  en:{q:"An RFI reaches the MINUKA RFI Manager with no dissemination details. What should happen?", o:["Task it anyway","Pass it to the JOC","Answer it verbally to whoever asks first, since dissemination details matter only for written products","Reject it and ask the requester to complete it"], e:"The PKISR Staff Handbook says RFIs lacking dissemination details must be rejected. The RFI Manager checks location, time and dissemination for every RFI."},
  bn:{q:"মিনুকার RFI ব্যবস্থাপকের কাছে বিতরণের বিবরণ ছাড়া একটি RFI এসেছে। কী করা উচিত?", o:["তবুও টাস্ক দিন","JOC-তে পাঠিয়ে দিন","যিনি আগে জিজ্ঞেস করবেন তাঁকে মৌখিকভাবে উত্তর দিন, কারণ বিতরণের বিবরণ কেবল লিখিত পণ্যের জন্যই প্রয়োজন হয়","প্রত্যাখ্যান করুন এবং অনুরোধকারীকে তা পূরণ করতে বলুন"], e:"PKISR স্টাফ হ্যান্ডবুক বলে, বিতরণের বিবরণ ছাড়া RFI প্রত্যাখ্যান করতে হবে। RFI ব্যবস্থাপক প্রতিটি RFI-এর স্থান, সময় ও বিতরণ যাচাই করেন।"},
  fr:{q:"Une RFI parvient au gestionnaire des RFI de la MINUKA sans instructions de diffusion. Que faire ?", o:["La traiter quand même","La transmettre au JOC","Répondre oralement au premier qui demande, car la diffusion ne compte que pour les produits écrits","La rejeter et demander au demandeur de la compléter"], e:"Le manuel PKISR prévoit que les RFI sans instructions de diffusion doivent être rejetées. Le gestionnaire vérifie le lieu, le délai et la diffusion de chaque RFI."}},
 /* ---------- m5 AOE ---------- */
 {m:"m5", a:0,
  en:{q:"A new G2 in Sector Central must start an Analysis of the Operating Environment. What are its three phases in the MPKI Handbook?", o:["Operating environment evaluation, actor evaluation, situation integration","Plan, collect, report","Terrain, weather, enemy","Mandate review, budget planning and a logistics estimate, followed by a final review of the plan by the troop-contributing capital"], e:"Phase 1 evaluates the physical, human and information terrain; Phase 2 evaluates all relevant actors; Phase 3 integrates them into actor courses of action."},
  bn:{q:"সেক্টর সেন্ট্রালের একজন নতুন G2-কে কার্যপরিবেশের বিশ্লেষণ শুরু করতে হবে। MPKI হ্যান্ডবুকে এর তিনটি পর্যায় কী?", o:["কার্যপরিবেশ মূল্যায়ন, অ্যাক্টর মূল্যায়ন, পরিস্থিতি সমন্বয়","পরিকল্পনা, সংগ্রহ, প্রতিবেদন","ভূখণ্ড, আবহাওয়া, শত্রু","ম্যান্ডেট পর্যালোচনা, বাজেট পরিকল্পনা ও লজিস্টিক প্রাক্কলন, তারপর সৈন্য প্রদানকারী দেশের রাজধানীতে পরিকল্পনার চূড়ান্ত পর্যালোচনা ও অনুমোদন"], e:"প্রথম পর্যায়ে ভৌত, মানব ও তথ্য ভূখণ্ড মূল্যায়ন; দ্বিতীয় পর্যায়ে সব প্রাসঙ্গিক অ্যাক্টরের মূল্যায়ন; তৃতীয় পর্যায়ে এগুলো মিলিয়ে অ্যাক্টরের কর্মপন্থা তৈরি করা হয়।"},
  fr:{q:"Un nouveau G2 du secteur Centre doit lancer une analyse de l’environnement opérationnel. Quelles en sont les trois phases selon le manuel MPKI ?", o:["Évaluation de l’environnement, évaluation des acteurs, intégration de la situation","Planifier, collecter, rendre compte","Terrain, météo, ennemi","Revue du mandat, planification budgétaire et estimation logistique, suivies d’un examen final du plan par la capitale du pays contributeur"], e:"La phase 1 évalue le terrain physique, humain et informationnel ; la phase 2 évalue tous les acteurs pertinents ; la phase 3 les intègre en modes d’action des acteurs."}},
 {m:"m5", a:1,
  en:{q:"A MINUKA G2 analyst wants to mark threat areas directly on the cell’s only large-scale map. What does the MPKI Handbook advise?", o:["Mark it in red ink","Use a labelled overlay; never draw on the map","Mark it lightly in pencil","Draw on it freely, because the map belongs to the cell and overlays are only needed for products shown to the Force Commander"], e:"Use themed overlays labelled with DTG, title, legend, north pointer, map series and edition, and two grid cross-marks. Do not draw on maps."},
  bn:{q:"মিনুকার একজন G2 বিশ্লেষক সেলের একমাত্র বড় স্কেলের মানচিত্রে সরাসরি হুমকির এলাকা চিহ্নিত করতে চান। MPKI হ্যান্ডবুক কী পরামর্শ দেয়?", o:["লাল কালিতে চিহ্নিত করুন","লেবেলযুক্ত ওভারলে ব্যবহার করুন; মানচিত্রে কখনো আঁকবেন না","হালকা পেনসিলে চিহ্নিত করুন","অবাধে আঁকুন, কারণ মানচিত্রটি সেলের নিজস্ব এবং ওভারলে কেবল ফোর্স কমান্ডারকে দেখানো পণ্যের জন্যই প্রয়োজন হয়"], e:"DTG, শিরোনাম, লেজেন্ড, উত্তর নির্দেশক, মানচিত্রের সিরিজ ও সংস্করণ এবং দুটি গ্রিড ক্রস-চিহ্নসহ বিষয়ভিত্তিক ওভারলে ব্যবহার করুন। মানচিত্রে আঁকবেন না।"},
  fr:{q:"Un analyste G2 de la MINUKA veut porter les zones de menace directement sur la seule carte à grande échelle de la cellule. Que conseille le manuel MPKI ?", o:["Les marquer à l’encre rouge","Utiliser un calque légendé ; ne jamais dessiner sur la carte","Les marquer légèrement au crayon","Dessiner librement, car la carte appartient à la cellule et les calques ne servent qu’aux produits présentés au commandant"], e:"Utilisez des calques thématiques portant le groupe date-heure, le titre, la légende, la flèche du nord, la série et l’édition de la carte et deux croix de carroyage. Ne dessinez pas sur les cartes."}},
 {m:"m5", a:2,
  en:{q:"Which of these is one of the five human terrain tools named in the MPKI Handbook for a MINUKA sector AOE?", o:["Mobility corridor overlay","Weather effects matrix","Items of High Importance list","A detailed equipment inventory of the Force’s own contingents compared with the host-State army’s holdings"], e:"The five tools are the ASCOPE-PMESII matrix, human terrain mapping overlays, link analysis, gender analysis and the Items of High Importance list. Mobility corridors and weather belong to physical terrain."},
  bn:{q:"মিনুকার একটি সেক্টর AOE-এর জন্য MPKI হ্যান্ডবুকে উল্লিখিত মানব ভূখণ্ডের পাঁচটি সরঞ্জামের একটি কোনটি?", o:["চলাচল করিডোর ওভারলে","আবহাওয়ার প্রভাব ম্যাট্রিক্স","উচ্চ গুরুত্বের বিষয়ের তালিকা","আয়োজক রাষ্ট্রের সেনাবাহিনীর মজুতের সঙ্গে তুলনা করে ফোর্সের নিজস্ব কন্টিনজেন্টগুলোর সরঞ্জামের বিস্তারিত তালিকা"], e:"পাঁচটি সরঞ্জাম হলো ASCOPE-PMESII ম্যাট্রিক্স, মানব ভূখণ্ড ম্যাপিং ওভারলে, লিংক বিশ্লেষণ, জেন্ডার বিশ্লেষণ এবং উচ্চ গুরুত্বের বিষয়ের তালিকা। চলাচল করিডোর ও আবহাওয়া ভৌত ভূখণ্ডের অংশ।"},
  fr:{q:"Lequel de ces éléments fait partie des cinq outils du terrain humain cités par le manuel MPKI pour l’AOE d’un secteur de la MINUKA ?", o:["Calque des couloirs de mobilité","Matrice des effets météorologiques","Liste des éléments de haute importance","Un inventaire détaillé des équipements des contingents de la Force comparé aux dotations de l’armée de l’État hôte"], e:"Les cinq outils sont la matrice ASCOPE-PMESII, les calques de cartographie du terrain humain, l’analyse des liens, l’analyse de genre et la liste des éléments de haute importance. Couloirs de mobilité et météo relèvent du terrain physique."}},
 {m:"m5", a:3,
  en:{q:"In Phase 3 of a MINUKA AOE, the G2 applies the FACES test. What does it check?", o:["Source reliability","Weather impact on patrols","Whether a briefing is short enough to give the commander within the thirty-minute limit for planning briefs","Whether an actor course of action is feasible, acceptable, complete, exclusive and suitable"], e:"FACES tests each actor course of action. Note that the SPIE text lists the criteria in a different order and wording; follow the mission SOP."},
  bn:{q:"মিনুকার AOE-এর তৃতীয় পর্যায়ে G2 FACES পরীক্ষা প্রয়োগ করেন। এটি কী যাচাই করে?", o:["উৎসের নির্ভরযোগ্যতা","টহলে আবহাওয়ার প্রভাব","পরিকল্পনা ব্রিফের ত্রিশ মিনিটের সীমার মধ্যে কমান্ডারকে দেওয়ার মতো যথেষ্ট সংক্ষিপ্ত একটি ব্রিফিং হয়েছে কি না এবং সময়মতো শেষ হবে কি না","অ্যাক্টরের কর্মপন্থা সম্ভবপর, গ্রহণযোগ্য, সম্পূর্ণ, স্বতন্ত্র ও উপযুক্ত কি না"], e:"FACES প্রতিটি অ্যাক্টরের কর্মপন্থা যাচাই করে। লক্ষ করুন, SPIE অংশে মানদণ্ডগুলো ভিন্ন ক্রম ও শব্দে আছে; মিশনের SOP অনুসরণ করুন।"},
  fr:{q:"En phase 3 d’une AOE de la MINUKA, le G2 applique le test FACES. Que vérifie-t-il ?", o:["La fiabilité des sources","L’effet de la météo sur les patrouilles","Si un exposé est assez court pour être présenté au commandant dans la limite de trente minutes prévue pour les exposés de planification","Si un mode d’action d’acteur est faisable, acceptable, complet, exclusif et adapté"], e:"FACES teste chaque mode d’action d’acteur. Le texte sur la SPIE présente les critères dans un autre ordre et avec d’autres termes ; suivez la SOP de la mission."}},
 /* ---------- m6 ACQUISITION ---------- */
 {m:"m6", a:0,
  en:{q:"In MINUKA Force HQ, who normally holds tasking authority for acquisition assets?", o:["Operations, unless the assets are OPCON to MPKI","Any patrol leader","The JMAC","The PKISR unit itself, which may re-task its own flights whenever it judges that a better target has appeared"], e:"MPKI builds the IAP; Operations normally generates and deconflicts tasks. UAS units must not re-task themselves; PKISR Ops decides."},
  bn:{q:"মিনুকা ফোর্স সদর দপ্তরে সাধারণত সংগ্রহ সম্পদের টাস্কিং কর্তৃত্ব কার হাতে থাকে?", o:["অপারেশন শাখার, যদি না সম্পদ MPKI-এর OPCON-এ থাকে","যেকোনো টহল নেতার","JMAC-এর","PKISR ইউনিটের নিজের, যা ভালো লক্ষ্য দেখা দিয়েছে মনে করলে যেকোনো সময় নিজের উড্ডয়ন নতুন করে নির্ধারণ করতে পারে"], e:"MPKI IAP তৈরি করে; অপারেশন শাখা সাধারণত কাজ তৈরি ও সমন্বয় করে। UAS ইউনিট নিজে থেকে কাজ বদলাতে পারে না; PKISR অপারেশন সিদ্ধান্ত নেয়।"},
  fr:{q:"Au QG de la Force de la MINUKA, qui détient normalement l’autorité de tâche sur les moyens d’acquisition ?", o:["Les opérations, sauf si les moyens sont sous OPCON du MPKI","Tout chef de patrouille","Le JMAC","L’unité PKISR elle-même, qui peut réaffecter ses vols chaque fois qu’elle estime qu’une meilleure cible est apparue"], e:"Le MPKI élabore l’IAP ; les opérations génèrent et coordonnent normalement les tâches. Les unités UAS ne se réaffectent pas elles-mêmes ; PKISR Ops décide."}},
 {m:"m6", a:1,
  en:{q:"The Sector North G2 is asked to gather information about a camp across the border in a neighbouring State. What is the correct response?", o:["Proceed if it can be done quickly","Decline; there is no acquisition outside the APIR, so refer it up","Proceed using civilians only","Proceed with staff work at headquarters only, since the APIR limit applies to patrols and never to staff at headquarters"], e:"The MPKI Handbook states there can be no acquisition activities outside the APIR, for example across a border in another State. Refer the request up the chain."},
  bn:{q:"সেক্টর নর্থের G2-কে প্রতিবেশী রাষ্ট্রে সীমান্তের ওপারের একটি শিবির সম্পর্কে তথ্য সংগ্রহ করতে বলা হলো। সঠিক প্রতিক্রিয়া কী?", o:["দ্রুত করা গেলে এগিয়ে যান","প্রত্যাখ্যান করুন; APIR-এর বাইরে কোনো সংগ্রহ নয়, তাই ওপরে জানান","কেবল বেসামরিক লোক দিয়ে এগিয়ে যান","কেবল সদর দপ্তরের স্টাফ কাজ দিয়ে এগিয়ে যান, কারণ APIR-এর সীমা টহলের ক্ষেত্রে প্রযোজ্য, সদর দপ্তরের স্টাফের ক্ষেত্রে কখনো নয়"], e:"MPKI হ্যান্ডবুক বলে, APIR-এর বাইরে কোনো সংগ্রহ কার্যক্রম হতে পারে না, যেমন অন্য রাষ্ট্রে সীমান্তের ওপারে। অনুরোধটি চেইন অব কমান্ডে জানান।"},
  fr:{q:"Le G2 du secteur Nord est prié de recueillir des informations sur un camp situé de l’autre côté de la frontière, dans un État voisin. Quelle est la bonne réponse ?", o:["Procéder si c’est rapide","Refuser ; aucune acquisition hors de l’APIR, en référer à l’échelon supérieur","Procéder avec des civils seulement","Procéder par un travail d’état-major au QG, car la limite de l’APIR vise les patrouilles et jamais l’état-major"], e:"Le manuel MPKI précise qu’aucune activité d’acquisition n’est possible hors de l’APIR, par exemple de l’autre côté d’une frontière dans un autre État. Transmettez la demande à la chaîne de commandement."}},
 {m:"m6", a:2,
  en:{q:"The MPKI Handbook says “every personnel is a sensor”. What does this mean for a MINUKA infantry company?", o:["Soldiers may run informants","Every soldier collects covertly","Patrols, posts and positive contact with people all feed reporting","Each soldier must carry recording equipment at all times and send raw footage directly to the Force Commander"], e:"Patrols, observation posts, base security and positive interaction with the population are all acquisition, done openly and reported through the S2."},
  bn:{q:"MPKI হ্যান্ডবুক বলে “প্রত্যেক সদস্যই একটি সেন্সর”। মিনুকার একটি পদাতিক কোম্পানির জন্য এর অর্থ কী?", o:["সৈন্যরা তথ্যদাতা চালাতে পারে","প্রত্যেক সৈন্য গোপনে সংগ্রহ করে","টহল, পোস্ট ও মানুষের সঙ্গে ইতিবাচক যোগাযোগ সবই প্রতিবেদনে যুক্ত হয়","প্রত্যেক সৈন্যকে সবসময় রেকর্ডিং সরঞ্জাম বহন করতে হবে এবং কাঁচা ফুটেজ সরাসরি ফোর্স কমান্ডারের কাছে পাঠাতে হবে"], e:"টহল, পর্যবেক্ষণ পোস্ট, ঘাঁটির নিরাপত্তা এবং জনগণের সঙ্গে ইতিবাচক যোগাযোগ সবই সংগ্রহ, যা প্রকাশ্যে করা হয় এবং S2-এর মাধ্যমে জানানো হয়।"},
  fr:{q:"Le manuel MPKI affirme que « chaque membre du personnel est un capteur ». Qu’est-ce que cela signifie pour une compagnie d’infanterie de la MINUKA ?", o:["Les soldats peuvent gérer des informateurs","Chaque soldat collecte en secret","Patrouilles, postes et contacts positifs avec la population alimentent tous les comptes rendus","Chaque soldat doit porter en permanence un équipement d’enregistrement et envoyer les images brutes directement au commandant de la force"], e:"Patrouilles, postes d’observation, sécurité de la base et interaction positive avec la population relèvent tous de l’acquisition, menée ouvertement et rapportée par le S2."}},
 {m:"m6", a:3,
  en:{q:"A MINUKA patrol returns to its company operating base. What does the MPKI Handbook require?", o:["Nothing unless shots were fired","A written essay by each soldier","A debrief only if the patrol leader thinks something important happened and the company commander approves it","A mandatory post-patrol debrief by MPKI staff"], e:"Annex E of the MPKI Handbook sets a pre-patrol brief and a mandatory post-patrol debrief by MPKI staff, so that what the patrol saw reaches the cell."},
  bn:{q:"মিনুকার একটি টহল তার কোম্পানি অপারেটিং ঘাঁটিতে ফিরল। MPKI হ্যান্ডবুক কী বাধ্যতামূলক করে?", o:["গুলি না চললে কিছুই না","প্রত্যেক সৈন্যের লিখিত রচনা","কেবল তখনই ডিব্রিফ, যখন টহল নেতা মনে করেন গুরুত্বপূর্ণ কিছু ঘটেছে এবং কোম্পানি কমান্ডার তা অনুমোদন করেন","MPKI স্টাফের বাধ্যতামূলক টহল-পরবর্তী ডিব্রিফ"], e:"MPKI হ্যান্ডবুকের সংযোজনী E টহলের আগে ব্রিফ এবং MPKI স্টাফের বাধ্যতামূলক টহল-পরবর্তী ডিব্রিফ নির্ধারণ করে, যাতে টহল যা দেখেছে তা সেলে পৌঁছায়।"},
  fr:{q:"Une patrouille de la MINUKA rentre à sa base opérationnelle de compagnie. Qu’exige le manuel MPKI ?", o:["Rien, sauf s’il y a eu des tirs","Une rédaction écrite par chaque soldat","Un débriefing seulement si le chef de patrouille juge qu’un fait important s’est produit et que le commandant de compagnie l’approuve","Un débriefing obligatoire après patrouille par le personnel MPKI"], e:"L’annexe E du manuel MPKI prévoit un briefing avant patrouille et un débriefing obligatoire après patrouille par le personnel MPKI, pour que ce que la patrouille a vu parvienne à la cellule."}},
 /* ---------- m7 ANALYSIS ---------- */
 {m:"m7", a:0,
  en:{q:"A MINUKA S2 receives a report from a usually reliable source; the information is logical and consistent but not confirmed. Which grade fits?", o:["B2","A1","C3","B1, since a usually reliable source makes the information confirmed"], e:"The letter rates the source (B, usually reliable) and the figure rates the information (2, probably true). Rate the two independently."},
  bn:{q:"মিনুকার একজন S2 সাধারণত নির্ভরযোগ্য একটি উৎস থেকে প্রতিবেদন পেলেন; তথ্যটি যৌক্তিক ও সামঞ্জস্যপূর্ণ কিন্তু নিশ্চিত নয়। কোন মান উপযুক্ত?", o:["B2","A1","C3","B1, কারণ সাধারণত নির্ভরযোগ্য উৎস হলেই তথ্য নিশ্চিত বলে ধরা হয়"], e:"অক্ষরটি উৎসের মান (B, সাধারণত নির্ভরযোগ্য) এবং সংখ্যাটি তথ্যের মান (2, সম্ভবত সত্য) নির্দেশ করে। দুটি আলাদাভাবে মূল্যায়ন করুন।"},
  fr:{q:"Un S2 de la MINUKA reçoit un compte rendu d’une source généralement fiable ; l’information est logique et cohérente mais non confirmée. Quelle cotation convient ?", o:["B2","A1","C3","B1, car une source généralement fiable rend l’information confirmée"], e:"La lettre cote la source (B, généralement fiable) et le chiffre cote l’information (2, probablement vraie). Cotez les deux de façon indépendante."}},
 {m:"m7", a:1,
  en:{q:"Two reports to the Sector East G2 agree on an armed group’s move, but both trace back to the same local radio broadcast. How should they be treated?", o:["As two independent confirmations","As circular reporting: count them as one source","Grade both A1","As proof that the move has happened, because two separate units sent the reports on the same day"], e:"The MPKI Handbook warns that circular reporting should be avoided at all times. Compare truly independent sources before raising confidence."},
  bn:{q:"সেক্টর ইস্টের G2-এর কাছে আসা দুটি প্রতিবেদন একটি সশস্ত্র গোষ্ঠীর অবস্থান পরিবর্তনে একমত, কিন্তু দুটিরই উৎস একই স্থানীয় রেডিও সম্প্রচার। এগুলোকে কীভাবে দেখবেন?", o:["দুটি স্বাধীন নিশ্চিতকরণ হিসেবে","চক্রাকার প্রতিবেদন হিসেবে: একটি উৎস ধরুন","দুটিকেই A1 মান দিন","অবস্থান পরিবর্তন ঘটেছে তার প্রমাণ হিসেবে, কারণ দুটি আলাদা ইউনিট একই দিনে প্রতিবেদন দুটি পাঠিয়েছে"], e:"MPKI হ্যান্ডবুক সতর্ক করে যে চক্রাকার প্রতিবেদন সবসময় এড়াতে হবে। আস্থা বাড়ানোর আগে সত্যিকারের স্বাধীন উৎসের সঙ্গে মিলিয়ে দেখুন।"},
  fr:{q:"Deux comptes rendus reçus par le G2 du secteur Est concordent sur le déplacement d’un groupe armé, mais tous deux remontent à la même émission de radio locale. Comment les traiter ?", o:["Comme deux confirmations indépendantes","Comme un compte rendu circulaire : une seule source","Coter les deux A1","Comme la preuve que le déplacement a eu lieu, puisque deux unités distinctes ont envoyé les comptes rendus le même jour"], e:"Le manuel MPKI avertit qu’il faut toujours éviter les comptes rendus circulaires. Comparez des sources réellement indépendantes avant d’accroître la confiance."}},
 {m:"m7", a:2,
  en:{q:"A MINUKA analyst writes “probable” in a draft assessment for the Force Commander. What should the cell do?", o:["Nothing; everyone understands it","Replace it with “certain”","Use the mission’s agreed probability yardstick and state confidence","Avoid all probability words and give only raw facts, because the commander must make every judgement himself"], e:"Readers may take “probable” as anything from 25 to 90 percent. Use the agreed yardstick, state assumptions and source grades, and separate fact from judgement."},
  bn:{q:"মিনুকার একজন বিশ্লেষক ফোর্স কমান্ডারের জন্য খসড়া মূল্যায়নে “সম্ভাব্য” লিখেছেন। সেলের কী করা উচিত?", o:["কিছুই না; সবাই এটি বোঝে","“নিশ্চিত” দিয়ে বদলে দিন","মিশনের সম্মত সম্ভাবনা মাপকাঠি ব্যবহার করুন এবং আস্থার মাত্রা বলুন","সম্ভাবনার সব শব্দ বাদ দিয়ে কেবল কাঁচা তথ্য দিন, কারণ প্রতিটি বিচার কমান্ডারকে নিজেই করতে হবে এবং বিশ্লেষক তা করবেন না"], e:"পাঠকেরা “সম্ভাব্য” শব্দকে ২৫ থেকে ৯০ শতাংশের যেকোনো অর্থে নিতে পারেন। সম্মত মাপকাঠি ব্যবহার করুন, অনুমান ও উৎসের মান বলুন এবং তথ্য ও বিচার আলাদা রাখুন।"},
  fr:{q:"Un analyste de la MINUKA écrit « probable » dans un projet d’évaluation pour le commandant de la force. Que doit faire la cellule ?", o:["Rien ; tout le monde comprend","Le remplacer par « certain »","Utiliser l’échelle de probabilité convenue de la mission et indiquer le degré de confiance","Éviter tout terme de probabilité et ne donner que des faits bruts, car le commandant doit porter seul chaque jugement"], e:"Les lecteurs peuvent comprendre « probable » comme n’importe quoi entre 25 et 90 %. Utilisez l’échelle convenue, indiquez hypothèses et cotations, et séparez les faits du jugement."}},
 {m:"m7", a:3,
  en:{q:"A MINUKA G2 cell uses Analysis of Competing Hypotheses on the Dalo incidents. Which hypothesis should it favour?", o:["The one with the most consistent evidence","The commander’s preferred one","The first hypothesis proposed by the most senior analyst, since experience outweighs inconsistent evidence","The one with the least inconsistent evidence"], e:"ACH works by trying to disprove hypotheses: the one with the least evidence against it is favoured. Consistent evidence often fits several hypotheses at once."},
  bn:{q:"মিনুকার একটি G2 সেল দালোর ঘটনাগুলোতে প্রতিযোগী অনুমানের বিশ্লেষণ ব্যবহার করছে। কোন অনুমানকে অগ্রাধিকার দেওয়া উচিত?", o:["যেটির পক্ষে সবচেয়ে বেশি সামঞ্জস্যপূর্ণ প্রমাণ","কমান্ডারের পছন্দের অনুমান","সবচেয়ে জ্যেষ্ঠ বিশ্লেষকের প্রস্তাবিত প্রথম অনুমান, কারণ অভিজ্ঞতা অসামঞ্জস্যপূর্ণ প্রমাণের চেয়ে বেশি গুরুত্বপূর্ণ বলে ধরা হয়","যেটির বিপক্ষে সবচেয়ে কম অসামঞ্জস্যপূর্ণ প্রমাণ"], e:"ACH অনুমানগুলো খণ্ডনের চেষ্টা করে কাজ করে: যার বিপক্ষে সবচেয়ে কম প্রমাণ, সেটিকে অগ্রাধিকার দেওয়া হয়। সামঞ্জস্যপূর্ণ প্রমাণ প্রায়ই একাধিক অনুমানের সঙ্গে মিলে যায়।"},
  fr:{q:"Une cellule G2 de la MINUKA applique l’analyse d’hypothèses concurrentes aux incidents de Dalo. Quelle hypothèse doit-elle privilégier ?", o:["Celle qui a le plus d’éléments compatibles","Celle que préfère le commandant","La première hypothèse proposée par l’analyste le plus ancien, car l’expérience l’emporte sur les éléments contraires","Celle qui a le moins d’éléments incompatibles"], e:"L’ACH consiste à chercher à réfuter les hypothèses : on privilégie celle qui a le moins d’éléments contre elle. Les éléments compatibles s’accordent souvent avec plusieurs hypothèses."}},
 /* ---------- m8 PRODUCTS ---------- */
 {m:"m8", a:0,
  en:{q:"A MINUKA patrol learns that an attack on a village is expected within 30 minutes. What should the S2 do with this?", o:["Pass the warning at once by the fastest means; withhold source detail","Wait for the next INTSUM","Write a full INTREP first","Hold it until the information has been graded and confirmed by a second independent source, to avoid false alarms in the sector"], e:"Threat-to-life information is passed immediately by the fastest means. The protective action may go over insecure means, but not the source or the analysis."},
  bn:{q:"মিনুকার একটি টহল জানতে পারল যে ৩০ মিনিটের মধ্যে একটি গ্রামে হামলা হতে পারে। S2 এটি নিয়ে কী করবেন?", o:["দ্রুততম উপায়ে সঙ্গে সঙ্গে সতর্কবার্তা দিন; উৎসের বিবরণ গোপন রাখুন","পরবর্তী INTSUM-এর জন্য অপেক্ষা করুন","আগে একটি পূর্ণ INTREP লিখুন","সেক্টরে ভুল সতর্কতা এড়াতে তথ্যের মান নির্ধারণ এবং দ্বিতীয় একটি স্বাধীন উৎস দ্বারা নিশ্চিত না হওয়া পর্যন্ত অপেক্ষা করে আটকে রাখুন"], e:"জীবনের ঝুঁকি-সংক্রান্ত তথ্য সঙ্গে সঙ্গে দ্রুততম উপায়ে পাঠাতে হয়। সুরক্ষামূলক পদক্ষেপ অনিরাপদ মাধ্যমে যেতে পারে, কিন্তু উৎস বা বিশ্লেষণ নয়।"},
  fr:{q:"Une patrouille de la MINUKA apprend qu’une attaque contre un village est attendue dans les 30 minutes. Que doit faire le S2 ?", o:["Transmettre l’alerte aussitôt par le moyen le plus rapide ; taire la source","Attendre la prochaine INTSUM","Rédiger d’abord un INTREP complet","La retenir jusqu’à ce que l’information soit cotée et confirmée par une deuxième source indépendante, pour éviter les fausses alertes dans le secteur"], e:"Une information de menace pour la vie est transmise immédiatement par le moyen le plus rapide. La mesure de protection peut passer par un moyen non sécurisé, mais ni la source ni l’analyse."}},
 {m:"m8", a:1,
  en:{q:"A non-routine, urgent event occurs in Sector Central. Which product should the G2 issue?", o:["An INTSUM","An INTREP","A thematic report","A PIE, because every urgent event requires a full estimate before any report at all can be sent"], e:"The INTREP is for non-routine, urgent reporting at any level, using 5WH. The INTSUM is periodic; thematic reports cover longer timescales."},
  bn:{q:"সেক্টর সেন্ট্রালে একটি অনিয়মিত, জরুরি ঘটনা ঘটেছে। G2 কোন পণ্য প্রকাশ করবেন?", o:["একটি INTSUM","একটি INTREP","একটি বিষয়ভিত্তিক প্রতিবেদন","একটি PIE, কারণ প্রতিটি জরুরি ঘটনায় যেকোনো প্রতিবেদন পাঠানোর আগে একটি পূর্ণ প্রাক্কলন তৈরি করা বাধ্যতামূলক"], e:"INTREP যেকোনো স্তরে অনিয়মিত, জরুরি প্রতিবেদনের জন্য, 5WH ব্যবহার করে। INTSUM পর্যায়ক্রমিক; বিষয়ভিত্তিক প্রতিবেদন দীর্ঘ সময় নিয়ে কাজ করে।"},
  fr:{q:"Un événement urgent et non périodique survient dans le secteur Centre. Quel produit le G2 doit-il diffuser ?", o:["Une INTSUM","Un INTREP","Un rapport thématique","Une PIE, car tout événement urgent exige une estimation complète avant qu’un compte rendu quelconque puisse être envoyé"], e:"L’INTREP sert aux comptes rendus urgents et non périodiques à tout niveau, selon les 5WH. L’INTSUM est périodique ; les rapports thématiques portent sur des délais plus longs."}},
 {m:"m8", a:2,
  en:{q:"A MINUKA G2 has e-mailed an urgent INTREP to three battalions. What must the G2 do next?", o:["Nothing; the job is done","Wait for the next briefing","Confirm the recipients know: proof of sending is not proof of receipt","Delete the e-mail after an hour so it cannot be forwarded, and assume that all recipients have read it and acted on it"], e:"The MPKI Handbook states that proof of sending is not proof of receipt; the originator must make sure recipients know. Log every dissemination."},
  bn:{q:"মিনুকার একজন G2 তিনটি ব্যাটালিয়নে একটি জরুরি INTREP ইমেইল করেছেন। এরপর G2-কে কী করতে হবে?", o:["কিছুই না; কাজ শেষ","পরবর্তী ব্রিফিংয়ের জন্য অপেক্ষা করুন","প্রাপকেরা জেনেছেন তা নিশ্চিত করুন: পাঠানোর প্রমাণ প্রাপ্তির প্রমাণ নয়","ফরোয়ার্ড ঠেকাতে এক ঘণ্টা পর ইমেইলটি মুছে দিন এবং ধরে নিন যে সব প্রাপক এটি পড়েছেন ও সে অনুযায়ী ব্যবস্থা নিয়েছেন"], e:"MPKI হ্যান্ডবুক বলে, পাঠানোর প্রমাণ প্রাপ্তির প্রমাণ নয়; প্রেরককে নিশ্চিত করতে হবে যে প্রাপকেরা জেনেছেন। প্রতিটি বিতরণ লগে লিখে রাখুন।"},
  fr:{q:"Un G2 de la MINUKA a envoyé par courriel un INTREP urgent à trois bataillons. Que doit-il faire ensuite ?", o:["Rien ; le travail est fait","Attendre le prochain briefing","Vérifier que les destinataires savent : preuve d’envoi n’est pas preuve de réception","Supprimer le courriel au bout d’une heure pour qu’il ne soit pas transféré, et supposer que tous l’ont lu et ont agi en conséquence"], e:"Le manuel MPKI précise que la preuve d’envoi n’est pas la preuve de réception ; l’auteur doit s’assurer que les destinataires sont informés. Consignez chaque diffusion."}},
 {m:"m8", a:3,
  en:{q:"The MINUKA Force must launch an operation tomorrow and there is no time for a full PIE. What should U2 produce?", o:["No analysis at all","Last year’s PIE, unchanged","A verbal brief from memory without written products, since written products are only needed for missions longer than a month","A SPIE"], e:"The SPIE is the written and graphic dissemination of the AOE, ending in actor course of action assessments, used when there is no time for a full PIE."},
  bn:{q:"মিনুকা ফোর্সকে আগামীকাল একটি অপারেশন শুরু করতে হবে এবং পূর্ণ PIE-এর সময় নেই। U2-এর কী তৈরি করা উচিত?", o:["কোনো বিশ্লেষণই নয়","গত বছরের PIE, অপরিবর্তিত","লিখিত পণ্য ছাড়া স্মৃতি থেকে মৌখিক ব্রিফ, কারণ লিখিত পণ্য কেবল এক মাসের বেশি সময়ের মিশনের জন্যই প্রয়োজন হয়","একটি SPIE"], e:"SPIE হলো AOE-এর লিখিত ও চিত্রভিত্তিক উপস্থাপন, যা অ্যাক্টরের কর্মপন্থার মূল্যায়ন দিয়ে শেষ হয়; পূর্ণ PIE-এর সময় না থাকলে এটি ব্যবহার করা হয়।"},
  fr:{q:"La Force de la MINUKA doit lancer une opération demain et le temps manque pour une PIE complète. Que doit produire le U2 ?", o:["Aucune analyse","La PIE de l’an dernier, inchangée","Un exposé oral de mémoire sans produit écrit, car les produits écrits ne servent qu’aux missions de plus d’un mois","Une SPIE"], e:"La SPIE est la diffusion écrite et graphique de l’AOE, conclue par l’évaluation des modes d’action des acteurs ; on l’utilise quand le temps manque pour une PIE complète."}},
 /* ---------- m9 PROTECTION ---------- */
 {m:"m9", a:0,
  en:{q:"A MINUKA trainer wants to cite the attack at Kadugli on 13 December 2025 in a force protection lesson. Which statement is accurate?", o:["Six Bangladeshi peacekeepers were killed and at least eight injured; do not attribute it","It was a cyber incident at UNHQ","No one was hurt","It is an exercise scenario invented for UN training with no real casualties, so it may be adapted freely to name any attacker the class prefers"], e:"At Kadugli on 13 December 2025, six Bangladeshi peacekeepers were killed and at least eight injured. Teach the facts without attributing responsibility."},
  bn:{q:"মিনুকার একজন প্রশিক্ষক ফোর্স সুরক্ষার পাঠে ১৩ ডিসেম্বর ২০২৫-এ কাদুগলির হামলার কথা উল্লেখ করতে চান। কোন বক্তব্যটি সঠিক?", o:["ছয়জন বাংলাদেশি শান্তিরক্ষী নিহত ও অন্তত আটজন আহত হন; দায় আরোপ করবেন না","এটি জাতিসংঘ সদর দপ্তরে একটি সাইবার ঘটনা","কেউ আহত হননি","এটি জাতিসংঘ প্রশিক্ষণের জন্য বানানো একটি অনুশীলন পরিস্থিতি, যাতে প্রকৃত হতাহত নেই, তাই ক্লাস যে হামলাকারীকে চায় তার নাম বসিয়ে অবাধে বদলানো যায়"], e:"১৩ ডিসেম্বর ২০২৫-এ কাদুগলিতে ছয়জন বাংলাদেশি শান্তিরক্ষী নিহত ও অন্তত আটজন আহত হন। দায় আরোপ না করে তথ্যগুলো শেখান।"},
  fr:{q:"Un formateur de la MINUKA veut citer l’attaque de Kadugli du 13 décembre 2025 dans une leçon sur la protection de la force. Quelle affirmation est exacte ?", o:["Six Casques bleus bangladais tués et au moins huit blessés ; ne pas l’attribuer","Un incident informatique au Siège de l’ONU","Personne n’a été blessé","Un scénario d’exercice inventé pour la formation de l’ONU, sans victimes réelles, que la classe peut adapter librement en nommant l’attaquant de son choix"], e:"À Kadugli, le 13 décembre 2025, six Casques bleus bangladais ont été tués et au moins huit blessés. Enseignez les faits sans attribuer la responsabilité."}},
 {m:"m9", a:1,
  en:{q:"Small unidentified drones have been seen twice over the MINUKA company operating base at Dalo. What is the S2’s role?", o:["Work out a method to bring them down","Report, assess the threat and recommend protection measures through the chain, under C-UAS guidance","Ignore them","Publish the sightings on social media to warn the population and ask local people to track the drone operators for the Force"], e:"The S2 reports, assesses and advises on protection within the chain of command and mission guidance, including the 2025 C-UAS Guidelines. Defeat methods are not part of PKI staff work or this course."},
  bn:{q:"দালোতে মিনুকার কোম্পানি অপারেটিং ঘাঁটির ওপর দুবার ছোট অজ্ঞাত ড্রোন দেখা গেছে। S2-এর ভূমিকা কী?", o:["সেগুলো নামানোর একটি পদ্ধতি বের করুন","C-UAS নির্দেশনা অনুযায়ী চেইনের মাধ্যমে প্রতিবেদন, হুমকি মূল্যায়ন ও সুরক্ষা ব্যবস্থার সুপারিশ","উপেক্ষা করুন","জনগণকে সতর্ক করতে সামাজিক মাধ্যমে দেখার খবর প্রকাশ করুন এবং স্থানীয় লোকদের ফোর্সের হয়ে ড্রোন পরিচালনাকারীদের খুঁজে বের করতে ও অনুসরণ করতে বলুন"], e:"S2 চেইন অব কমান্ড ও মিশনের নির্দেশনার মধ্যে, ২০২৫ সালের C-UAS নির্দেশিকাসহ, প্রতিবেদন দেন, মূল্যায়ন করেন ও সুরক্ষা বিষয়ে পরামর্শ দেন। প্রতিরোধের পদ্ধতি PKI স্টাফের কাজ বা এই কোর্সের অংশ নয়।"},
  fr:{q:"De petits drones non identifiés ont été vus deux fois au-dessus de la base opérationnelle de compagnie de la MINUKA à Dalo. Quel est le rôle du S2 ?", o:["Mettre au point une méthode pour les abattre","Rendre compte, évaluer la menace et recommander des mesures de protection par la chaîne, selon les orientations C-UAS","Les ignorer","Publier les observations sur les réseaux sociaux pour alerter la population et demander aux habitants de pister les opérateurs de drones pour la Force"], e:"Le S2 rend compte, évalue et conseille sur la protection dans le cadre de la chaîne de commandement et des orientations de la mission, dont les Directives C-UAS de 2025. Les méthodes de neutralisation ne relèvent ni du travail PKI ni de ce cours."}},
 {m:"m9", a:2,
  en:{q:"A MINUKA patrol reports that women and children have stopped using the market in Weru. How should the S2 treat this?", o:["As irrelevant","As a humanitarian matter only","As a possible gender early warning indicator to log and link to a NAI","As proof that an attack will happen within 24 hours, so the Force must strike the nearest armed group immediately"], e:"Changes in the presence of women, children and the elderly are indicator examples in the MPKI Handbook. Record them with disaggregated data, tie them to a NAI and monitor."},
  bn:{q:"মিনুকার একটি টহল জানাল যে ওয়েরুর বাজারে নারী ও শিশুরা যাওয়া বন্ধ করেছে। S2 এটিকে কীভাবে দেখবেন?", o:["অপ্রাসঙ্গিক হিসেবে","কেবল মানবিক বিষয় হিসেবে","লগে লেখা ও একটি NAI-এর সঙ্গে যুক্ত করার মতো সম্ভাব্য জেন্ডার আগাম সতর্কতা নির্দেশক হিসেবে","২৪ ঘণ্টার মধ্যে হামলা হবে তার প্রমাণ হিসেবে, তাই ফোর্সকে অবিলম্বে নিকটতম সশস্ত্র গোষ্ঠীর ওপর আঘাত হানতে হবে এবং দেরি করা চলবে না"], e:"নারী, শিশু ও বয়স্কদের উপস্থিতির পরিবর্তন MPKI হ্যান্ডবুকের নির্দেশক উদাহরণ। বিভাজিত উপাত্তসহ লিখে রাখুন, একটি NAI-এর সঙ্গে যুক্ত করুন এবং নজর রাখুন।"},
  fr:{q:"Une patrouille de la MINUKA signale que les femmes et les enfants ne fréquentent plus le marché de Weru. Comment le S2 doit-il traiter ce fait ?", o:["Comme sans intérêt","Comme une question uniquement humanitaire","Comme un possible indicateur d’alerte précoce lié au genre, à consigner et à rattacher à une NAI","Comme la preuve qu’une attaque aura lieu sous 24 heures, de sorte que la Force doit frapper immédiatement le groupe armé le plus proche"], e:"Les changements dans la présence des femmes, des enfants et des personnes âgées figurent parmi les exemples d’indicateurs du manuel MPKI. Consignez-les avec des données ventilées, rattachez-les à une NAI et suivez-les."}},
 {m:"m9", a:3,
  en:{q:"A MINUKA threat assessment finds that a local group has clear intent to harm the Force but no current capability. How should the threat be described?", o:["High threat","The same as capability without intent","Threat cannot be assessed at all until the group has publicly announced both its intent and its capability","Low current threat; watch for capability indicators"], e:"The MPKI Handbook breaks threat down as intent times capability. With no capability the current threat is low, but indicators of growing capability belong in the IAP."},
  bn:{q:"মিনুকার একটি হুমকি মূল্যায়নে দেখা গেল, একটি স্থানীয় গোষ্ঠীর ফোর্সের ক্ষতি করার স্পষ্ট উদ্দেশ্য আছে কিন্তু বর্তমানে কোনো সক্ষমতা নেই। হুমকিকে কীভাবে বর্ণনা করবেন?", o:["উচ্চ হুমকি","উদ্দেশ্য ছাড়া সক্ষমতার সমান","গোষ্ঠীটি প্রকাশ্যে তার উদ্দেশ্য ও সক্ষমতা দুটোই ঘোষণা না করা পর্যন্ত হুমকি একেবারেই মূল্যায়ন করা সম্ভব নয় এবং করা উচিতও নয়","বর্তমান হুমকি কম; সক্ষমতার নির্দেশকের ওপর নজর রাখুন"], e:"MPKI হ্যান্ডবুক হুমকিকে উদ্দেশ্য গুণ সক্ষমতা হিসেবে ভাঙে। সক্ষমতা না থাকলে বর্তমান হুমকি কম, তবে বাড়তে থাকা সক্ষমতার নির্দেশক IAP-এ রাখতে হবে।"},
  fr:{q:"Une évaluation de la menace de la MINUKA conclut qu’un groupe local a clairement l’intention de nuire à la Force mais aucune capacité actuelle. Comment qualifier la menace ?", o:["Menace élevée","Équivalente à une capacité sans intention","La menace ne peut pas du tout être évaluée tant que le groupe n’a pas annoncé publiquement son intention et sa capacité","Menace actuelle faible ; suivre les indicateurs de capacité"], e:"Le manuel MPKI décompose la menace en intention multipliée par capacité. Sans capacité, la menace actuelle est faible, mais les indicateurs d’une capacité croissante doivent figurer dans l’IAP."}},
 /* ---------- m10 HANDLING ---------- */
 {m:"m10", a:0,
  en:{q:"A MINUKA battalion wants an old UN CONFIDENTIAL Force product downgraded so it can be used in a public briefing. Who may downgrade it?", o:["Only the originating person or post","Any reader who needs it","The JOC duty officer","The most senior officer in the room who needs to share it, provided he notes the change in his personal diary"], e:"The MPKI Handbook says downgrading is done periodically and only by the originating person or post. Ask the originator."},
  bn:{q:"মিনুকার একটি ব্যাটালিয়ন একটি পুরোনো UN CONFIDENTIAL ফোর্স পণ্য প্রকাশ্য ব্রিফিংয়ে ব্যবহারের জন্য শ্রেণিমান কমাতে চায়। কে শ্রেণিমান কমাতে পারেন?", o:["কেবল মূল প্রণয়নকারী ব্যক্তি বা পদ","প্রয়োজন আছে এমন যেকোনো পাঠক","JOC-এর দায়িত্বরত কর্মকর্তা","কক্ষে উপস্থিত সবচেয়ে জ্যেষ্ঠ কর্মকর্তা যাঁর এটি ভাগ করা দরকার, যদি তিনি পরিবর্তনটি নিজের ব্যক্তিগত ডায়েরিতে লিখে রাখেন"], e:"MPKI হ্যান্ডবুক বলে, শ্রেণিমান পর্যায়ক্রমে এবং কেবল মূল প্রণয়নকারী ব্যক্তি বা পদ কমাতে পারেন। প্রণয়নকারীকে জিজ্ঞেস করুন।"},
  fr:{q:"Un bataillon de la MINUKA veut faire déclasser un ancien produit UN CONFIDENTIAL de la Force pour un exposé public. Qui peut le déclasser ?", o:["Seulement la personne ou le poste d’origine","Tout lecteur qui en a besoin","L’officier de permanence du JOC","L’officier le plus ancien présent qui doit le partager, à condition de noter le changement dans son carnet personnel"], e:"Selon le manuel MPKI, le déclassement se fait périodiquement et uniquement par la personne ou le poste d’origine. Adressez-vous à l’auteur."}},
 {m:"m10", a:1,
  en:{q:"A new MINUKA G2 clerk asks which classification levels apply to UN documents under ST/SGB/2007/6. What is the answer?", o:["Secret and Top Secret","Unclassified, Confidential, Strictly Confidential","Restricted only","Whatever levels each troop-contributing country uses nationally, applied by the contingent that wrote the report"], e:"ST/SGB/2007/6 sets three levels: unclassified, confidential and strictly confidential. Product templates show UN CONFIDENTIAL or UN STRICTLY CONFIDENTIAL as content requires."},
  bn:{q:"মিনুকার একজন নতুন G2 করণিক জানতে চাইলেন, ST/SGB/2007/6 অনুযায়ী জাতিসংঘের দলিলে কোন শ্রেণিমান প্রযোজ্য। উত্তর কী?", o:["সিক্রেট ও টপ সিক্রেট","অশ্রেণিভুক্ত, গোপনীয়, কঠোরভাবে গোপনীয়","কেবল সীমিত","প্রতিটি সৈন্য প্রদানকারী দেশ জাতীয়ভাবে যে মান ব্যবহার করে, প্রতিবেদন লেখা কন্টিনজেন্ট তা-ই প্রয়োগ করবে"], e:"ST/SGB/2007/6 তিনটি মান নির্ধারণ করে: অশ্রেণিভুক্ত, গোপনীয় ও কঠোরভাবে গোপনীয়। পণ্যের টেমপ্লেটে বিষয়বস্তু অনুযায়ী UN CONFIDENTIAL বা UN STRICTLY CONFIDENTIAL থাকে।"},
  fr:{q:"Un nouveau commis du G2 de la MINUKA demande quels niveaux de classification s’appliquent aux documents de l’ONU selon ST/SGB/2007/6. Quelle est la réponse ?", o:["Secret et Très secret","Non classifié, Confidentiel, Strictement confidentiel","Diffusion restreinte seulement","Les niveaux nationaux de chaque pays fournisseur de contingents, appliqués par le contingent auteur du compte rendu"], e:"ST/SGB/2007/6 fixe trois niveaux : non classifié, confidentiel et strictement confidentiel. Les modèles de produits portent UN CONFIDENTIAL ou UN STRICTLY CONFIDENTIAL selon le contenu."}},
 {m:"m10", a:2,
  en:{q:"A non-UN security force operating near Sector East asks MINUKA for a threat assessment. Who decides whether to share MPKI with it?", o:["Any battalion commander","The contingent’s national capital","The SRSG, who may delegate, applying the HRDDP","The Chief U2 alone on any day, without any assessment of how the partner force will use the information"], e:"The decision to share with non-UN partners rests with the SRSG, who may delegate. Weigh how the partner will use it, impartiality and reputational risk, and apply the HRDDP."},
  bn:{q:"সেক্টর ইস্টের কাছে কর্মরত একটি অ-জাতিসংঘ নিরাপত্তা বাহিনী মিনুকার কাছে একটি হুমকি মূল্যায়ন চাইল। তাদের সঙ্গে MPKI ভাগ করা হবে কি না, কে সিদ্ধান্ত নেন?", o:["যেকোনো ব্যাটালিয়ন কমান্ডার","কন্টিনজেন্টের জাতীয় রাজধানী","SRSG, যিনি দায়িত্ব অর্পণ করতে পারেন, HRDDP প্রয়োগ করে","যেকোনো দিন একা চিফ U2, অংশীদার বাহিনী তথ্যটি কীভাবে ব্যবহার করবে তার কোনো মূল্যায়ন ছাড়াই এবং কাউকে না জানিয়ে"], e:"অ-জাতিসংঘ অংশীদারদের সঙ্গে বিনিময়ের সিদ্ধান্ত SRSG-এর, যিনি দায়িত্ব অর্পণ করতে পারেন। অংশীদার কীভাবে ব্যবহার করবে, নিরপেক্ষতা ও সুনামের ঝুঁকি বিবেচনা করুন এবং HRDDP প্রয়োগ করুন।"},
  fr:{q:"Une force de sécurité non onusienne opérant près du secteur Est demande à la MINUKA une évaluation de la menace. Qui décide de partager le MPKI avec elle ?", o:["Tout commandant de bataillon","La capitale nationale du contingent","Le RSSG, qui peut déléguer, en appliquant la HRDDP","Le chef U2 seul, n’importe quel jour, sans évaluer l’usage que la force partenaire fera de l’information"], e:"La décision de partager avec des partenaires non onusiens revient au RSSG, qui peut déléguer. Il faut peser l’usage prévu, l’impartialité et le risque pour la réputation, et appliquer la HRDDP."}},
 {m:"m10", a:3,
  en:{q:"A MINUKA battalion holds a threat report from a sensitive source that the neighbouring battalion urgently needs. What should the S2 do?", o:["Not share it, to protect the source","Share all of it, including the source’s identity","Share it only after the next monthly PKIMB has met and formally approved the dissemination list for that month","Write for release: share the threat and protect the source"], e:"Need to share and write for release go together: decide what the recipient needs, pass the threat, and format the product to protect the source."},
  bn:{q:"মিনুকার একটি ব্যাটালিয়নের কাছে একটি সংবেদনশীল উৎস থেকে পাওয়া হুমকি প্রতিবেদন আছে, যা পাশের ব্যাটালিয়নের জরুরি প্রয়োজন। S2 কী করবেন?", o:["উৎস রক্ষায় ভাগ করবেন না","উৎসের পরিচয়সহ সবকিছু ভাগ করুন","কেবল পরবর্তী মাসিক PKIMB বসে সেই মাসের বিতরণ তালিকা আনুষ্ঠানিকভাবে অনুমোদন করার পরেই ভাগ করুন, তার আগে কোনোভাবেই নয়","প্রকাশযোগ্যভাবে লিখুন: হুমকি জানান, উৎস রক্ষা করুন"], e:"ভাগ করার প্রয়োজন ও প্রকাশযোগ্যভাবে লেখা একসঙ্গে চলে: প্রাপকের কী দরকার তা ঠিক করুন, হুমকিটি জানান এবং উৎস রক্ষা করে পণ্যটি সাজান।"},
  fr:{q:"Un bataillon de la MINUKA détient un compte rendu de menace issu d’une source sensible dont le bataillon voisin a un besoin urgent. Que doit faire le S2 ?", o:["Ne pas le partager, pour protéger la source","Tout partager, y compris l’identité de la source","Le partager seulement après la réunion du prochain PKIMB mensuel et l’approbation formelle de la liste de diffusion du mois","Rédiger pour diffusion : partager la menace, protéger la source"], e:"Besoin de partager et rédaction pour diffusion vont ensemble : déterminez ce dont le destinataire a besoin, transmettez la menace et présentez le produit de façon à protéger la source."}},
 /* ---------- m11 PEOPLE ---------- */
 {m:"m11", a:0,
  en:{q:"A troop-contributing country planner asks what the MPKI Handbook says about people posted to U2, G2 and S2 roles in a Force like MINUKA. What does it say?", o:["They should have rank and training commensurate with their roles","Any available officer will do","Only intelligence corps officers may serve","They must hold a UN-issued MPKI licence renewed every year by the Office of Military Affairs at UN Headquarters"], e:"The handbook asks for rank and training commensurate with roles but sets no formal selection standard. No UN list of minimum MPKI qualifications was found."},
  bn:{q:"একজন সৈন্য প্রদানকারী দেশের পরিকল্পনাকারী জানতে চাইলেন, মিনুকার মতো ফোর্সে U2, G2 ও S2 পদে নিয়োজিতদের সম্পর্কে MPKI হ্যান্ডবুক কী বলে। উত্তর কী?", o:["তাঁদের ভূমিকার উপযোগী পদমর্যাদা ও প্রশিক্ষণ থাকা উচিত","যেকোনো উপলব্ধ কর্মকর্তা হলেই চলবে","কেবল গোয়েন্দা কোরের কর্মকর্তারা দায়িত্ব পালন করতে পারেন","তাঁদের জাতিসংঘ সদর দপ্তরের সামরিক বিষয়ক কার্যালয় থেকে প্রতিবছর নবায়ন করা জাতিসংঘ-প্রদত্ত MPKI লাইসেন্স থাকতে হবে"], e:"হ্যান্ডবুক ভূমিকার উপযোগী পদমর্যাদা ও প্রশিক্ষণ চায়, তবে কোনো আনুষ্ঠানিক নির্বাচন মানদণ্ড নির্ধারণ করে না। ন্যূনতম MPKI যোগ্যতার কোনো জাতিসংঘ তালিকা পাওয়া যায়নি।"},
  fr:{q:"Un planificateur d’un pays fournisseur de contingents demande ce que dit le manuel MPKI des personnes affectées aux postes U2, G2 et S2 dans une Force comme la MINUKA. Que dit-il ?", o:["Elles doivent avoir un grade et une formation adaptés à leur rôle","N’importe quel officier disponible convient","Seuls les officiers du corps du renseignement peuvent servir","Elles doivent détenir une licence MPKI délivrée par l’ONU et renouvelée chaque année par le Bureau des affaires militaires au Siège"], e:"Le manuel demande un grade et une formation adaptés au rôle mais ne fixe aucune norme formelle de sélection. Aucune liste onusienne de qualifications minimales MPKI n’a été trouvée."}},
 {m:"m11", a:1,
  en:{q:"A MINUKA S2 cell is setting up its database. What does the MPKI Handbook say about the data it records?", o:["Record only male community leaders","All data is to be gender- and age-disaggregated","Gender matters only for civilian staff","Record gender only when the Force Commander asks for it in writing for a specific report or briefing"], e:"The MPKI Handbook says all data is to be gender- and age-disaggregated, and MPKI cells must incorporate a gender perspective."},
  bn:{q:"মিনুকার একটি S2 সেল তার ডেটাবেস তৈরি করছে। রেকর্ড করা উপাত্ত সম্পর্কে MPKI হ্যান্ডবুক কী বলে?", o:["কেবল পুরুষ সমাজনেতাদের তথ্য রাখুন","সব উপাত্ত জেন্ডার ও বয়স অনুযায়ী বিভাজিত হতে হবে","জেন্ডার কেবল বেসামরিক কর্মীদের বিষয়","কেবল তখনই জেন্ডার রেকর্ড করুন, যখন ফোর্স কমান্ডার কোনো নির্দিষ্ট প্রতিবেদন বা ব্রিফিংয়ের জন্য লিখিতভাবে তা চান"], e:"MPKI হ্যান্ডবুক বলে, সব উপাত্ত জেন্ডার ও বয়স অনুযায়ী বিভাজিত হবে এবং MPKI সেলকে জেন্ডার দৃষ্টিকোণ অন্তর্ভুক্ত করতে হবে।"},
  fr:{q:"Une cellule S2 de la MINUKA crée sa base de données. Que dit le manuel MPKI des données qu’elle enregistre ?", o:["N’enregistrer que les chefs communautaires masculins","Toutes les données doivent être ventilées par sexe et par âge","Le genre ne concerne que le personnel civil","N’enregistrer le genre que si le commandant de la force le demande par écrit pour un rapport ou un exposé précis"], e:"Le manuel MPKI dispose que toutes les données doivent être ventilées par sexe et par âge, et que les cellules MPKI doivent intégrer une perspective de genre."}},
 {m:"m11", a:2,
  en:{q:"A MINUKA instructor wants a figure for how many women served in U2, G2 and S2 posts worldwide in 2026. What should the instructor do?", o:["Quote 30 percent from memory","Say it is about half","Say no public figure was found and do not invent one","Use the figure from the instructor’s own national army and present it as the global UN figure for all missions"], e:"No public 2025-26 data on women in U2, G2 and S2 posts was found. Say so; never claim a figure without a source."},
  bn:{q:"মিনুকার একজন প্রশিক্ষক জানতে চান, ২০২৬ সালে বিশ্বজুড়ে U2, G2 ও S2 পদে কতজন নারী দায়িত্ব পালন করেছেন। প্রশিক্ষকের কী করা উচিত?", o:["স্মৃতি থেকে ৩০ শতাংশ বলুন","বলুন প্রায় অর্ধেক","বলুন কোনো প্রকাশ্য পরিসংখ্যান পাওয়া যায়নি এবং বানিয়ে বলবেন না","প্রশিক্ষকের নিজের জাতীয় সেনাবাহিনীর পরিসংখ্যান ব্যবহার করুন এবং সেটিকে সব মিশনের জন্য জাতিসংঘের বৈশ্বিক পরিসংখ্যান হিসেবে উপস্থাপন করুন"], e:"U2, G2 ও S2 পদে নারীদের বিষয়ে ২০২৫-২৬ সালের কোনো প্রকাশ্য উপাত্ত পাওয়া যায়নি। সেটিই বলুন; উৎস ছাড়া কখনো পরিসংখ্যান দাবি করবেন না।"},
  fr:{q:"Un formateur de la MINUKA cherche le nombre de femmes ayant servi dans des postes U2, G2 et S2 dans le monde en 2026. Que doit-il faire ?", o:["Citer 30 % de mémoire","Dire environ la moitié","Dire qu’aucun chiffre public n’a été trouvé et ne pas en inventer","Utiliser le chiffre de sa propre armée nationale et le présenter comme le chiffre mondial de l’ONU pour toutes les missions"], e:"Aucune donnée publique de 2025-2026 sur les femmes dans les postes U2, G2 et S2 n’a été trouvée. Dites-le ; n’avancez jamais un chiffre sans source."}},
 {m:"m11", a:3,
  en:{q:"The Sector North commander asks the G2 to change an assessment so that it supports the plan he prefers. What should the G2 do?", o:["Change it as asked","Leave out the inconvenient part","Resign from the post immediately and report the commander to the national capital through a personal channel","Keep the assessment, explain the evidence and record the commander’s decision"], e:"Objectivity requires moral courage: do not distort assessments to suit leadership. Explain the evidence clearly; the commander decides, and the record shows both."},
  bn:{q:"সেক্টর নর্থের কমান্ডার G2-কে একটি মূল্যায়ন এমনভাবে বদলাতে বললেন যাতে তা তাঁর পছন্দের পরিকল্পনাকে সমর্থন করে। G2 কী করবেন?", o:["যেভাবে বলা হয়েছে সেভাবে বদলান","অসুবিধাজনক অংশটি বাদ দিন","অবিলম্বে পদ থেকে পদত্যাগ করুন এবং ব্যক্তিগত চ্যানেলের মাধ্যমে কমান্ডারের বিরুদ্ধে জাতীয় রাজধানীতে অভিযোগ জানান","মূল্যায়ন বজায় রাখুন, প্রমাণ ব্যাখ্যা করুন এবং কমান্ডারের সিদ্ধান্ত লিখে রাখুন"], e:"বস্তুনিষ্ঠতার জন্য নৈতিক সাহস দরকার: নেতৃত্বকে খুশি করতে মূল্যায়ন বিকৃত করবেন না। প্রমাণ স্পষ্টভাবে ব্যাখ্যা করুন; সিদ্ধান্ত কমান্ডারের, আর নথিতে দুটোই থাকে।"},
  fr:{q:"Le commandant du secteur Nord demande au G2 de modifier une évaluation pour qu’elle soutienne le plan qu’il préfère. Que doit faire le G2 ?", o:["La modifier comme demandé","Supprimer la partie gênante","Démissionner aussitôt et dénoncer le commandant à la capitale nationale par un canal personnel","Maintenir l’évaluation, expliquer les éléments et consigner la décision du commandant"], e:"L’objectivité exige du courage moral : ne pas déformer les évaluations pour plaire à la hiérarchie. Expliquez clairement les éléments ; le commandant décide et le dossier garde trace des deux."}},
 /* ---------- m12 TRAINER ---------- */
 {m:"m12", a:0,
  en:{q:"During a MINUKA predeployment course, a student asks the instructor to show how to defeat a hostile drone. What should the instructor do?", o:["Decline; teach the policy and refer to authorized technical training","Demonstrate a method","Show an online video","Explain the method in general terms, since general explanations of drone weaknesses are acceptable in any public course"], e:"This course teaches roles, rules and decisions. Counter-drone defeat methods and weaknesses are outside public education; refer to authorized training and teach the policy level."},
  bn:{q:"মিনুকার একটি মোতায়েন-পূর্ব কোর্সে একজন শিক্ষার্থী প্রশিক্ষককে একটি শত্রু ড্রোন প্রতিহত করার উপায় দেখাতে বললেন। প্রশিক্ষক কী করবেন?", o:["প্রত্যাখ্যান করুন; নীতি শেখান এবং অনুমোদিত কারিগরি প্রশিক্ষণে পাঠান","একটি পদ্ধতি দেখান","একটি অনলাইন ভিডিও দেখান","সাধারণভাবে পদ্ধতিটি ব্যাখ্যা করুন, কারণ ড্রোনের দুর্বলতার সাধারণ ব্যাখ্যা যেকোনো প্রকাশ্য কোর্সে গ্রহণযোগ্য বলে ধরা হয়"], e:"এই কোর্স ভূমিকা, নিয়ম ও সিদ্ধান্ত শেখায়। ড্রোন প্রতিরোধের পদ্ধতি ও দুর্বলতা প্রকাশ্য শিক্ষার বাইরে; অনুমোদিত প্রশিক্ষণে পাঠান এবং নীতিগত স্তর শেখান।"},
  fr:{q:"Pendant un cours préalable au déploiement de la MINUKA, un stagiaire demande au formateur de montrer comment neutraliser un drone hostile. Que doit faire le formateur ?", o:["Refuser ; enseigner la politique et orienter vers une formation technique autorisée","Montrer une méthode","Diffuser une vidéo en ligne","Expliquer la méthode en termes généraux, car les explications générales sur les faiblesses des drones sont acceptables dans tout cours public"], e:"Ce cours enseigne les rôles, les règles et les décisions. Les méthodes de neutralisation et les faiblesses des drones sortent de l’éducation publique ; orientez vers une formation autorisée et restez au niveau de la politique."}},
 {m:"m12", a:1,
  en:{q:"A trainer is designing a 90-minute staff exercise for a MINUKA battalion S2 cell. Which design is best?", o:["A lecture with slides","Injects, time pressure, a red-line moment and a structured debrief","A quiz only","Real classified reporting from a current mission, so that the training feels as authentic as possible to the students"], e:"Good exercises use invented facts, realistic injects and time pressure, a moment that tests the rules, and a debrief. Never use live or restricted material."},
  bn:{q:"একজন প্রশিক্ষক মিনুকার একটি ব্যাটালিয়ন S2 সেলের জন্য ৯০ মিনিটের একটি স্টাফ অনুশীলন সাজাচ্ছেন। কোন নকশাটি সবচেয়ে ভালো?", o:["স্লাইডসহ একটি বক্তৃতা","ইনজেক্ট, সময়ের চাপ, একটি লাল-রেখার মুহূর্ত এবং কাঠামোবদ্ধ ডিব্রিফ","কেবল একটি কুইজ","চলমান কোনো মিশনের প্রকৃত শ্রেণিভুক্ত প্রতিবেদন, যাতে শিক্ষার্থীদের কাছে প্রশিক্ষণটি যতটা সম্ভব বাস্তব ও বিশ্বাসযোগ্য মনে হয়"], e:"ভালো অনুশীলনে বানানো তথ্য, বাস্তবসম্মত ইনজেক্ট ও সময়ের চাপ, নিয়ম যাচাইয়ের একটি মুহূর্ত এবং ডিব্রিফ থাকে। কখনো চলমান বা সংরক্ষিত উপকরণ ব্যবহার করবেন না।"},
  fr:{q:"Un formateur conçoit un exercice d’état-major de 90 minutes pour une cellule S2 de bataillon de la MINUKA. Quelle conception est la meilleure ?", o:["Un exposé avec diapositives","Des injects, une pression temporelle, un moment de ligne rouge et un débriefing structuré","Un simple quiz","De vrais comptes rendus classifiés d’une mission en cours, pour que la formation paraisse aussi authentique que possible aux stagiaires"], e:"Un bon exercice utilise des faits inventés, des injects réalistes et une pression temporelle, un moment qui met les règles à l’épreuve et un débriefing. N’utilisez jamais de matériel réel ou restreint."}},
 {m:"m12", a:2,
  en:{q:"A MINUKA trainer updates the reading list in November 2026. Which statement about the 2025 handbooks is accurate?", o:["They were superseded in 2026","They were never approved","MPKI Handbook 2025.10 and PKISR Staff Handbook 2025.15 are the latest found; check for newer","They replaced the 2019 PKI Policy, which no longer governs military peacekeeping-intelligence in any mission at all"], e:"The 2025 MPKI Handbook (approved May 2025) and the PKISR Staff Handbook are the latest versions found, under the 2019 Policy. Always check for newer versions."},
  bn:{q:"মিনুকার একজন প্রশিক্ষক নভেম্বর ২০২৬-এ পাঠ্যতালিকা হালনাগাদ করছেন। ২০২৫ সালের হ্যান্ডবুক সম্পর্কে কোন বক্তব্যটি সঠিক?", o:["২০২৬ সালে এগুলো বাতিল হয়েছে","এগুলো কখনো অনুমোদিত হয়নি","MPKI হ্যান্ডবুক 2025.10 ও PKISR স্টাফ হ্যান্ডবুক 2025.15 পাওয়া সর্বশেষ; নতুন আছে কি না যাচাই করুন","এগুলো ২০১৯ সালের PKI নীতিকে প্রতিস্থাপন করেছে, যা এখন আর কোনো মিশনেই সামরিক শান্তিরক্ষা-গোয়েন্দা তথ্যের ক্ষেত্রে প্রযোজ্য নয়"], e:"২০২৫ সালের MPKI হ্যান্ডবুক (মে ২০২৫-এ অনুমোদিত) ও PKISR স্টাফ হ্যান্ডবুক ২০১৯ সালের নীতির অধীনে পাওয়া সর্বশেষ সংস্করণ। সবসময় নতুন সংস্করণ যাচাই করুন।"},
  fr:{q:"Un formateur de la MINUKA met à jour la liste de lectures en novembre 2026. Quelle affirmation sur les manuels de 2025 est exacte ?", o:["Ils ont été remplacés en 2026","Ils n’ont jamais été approuvés","Les manuels MPKI 2025.10 et PKISR 2025.15 sont les derniers trouvés ; vérifier s’il en existe de plus récents","Ils ont remplacé la Politique PKI de 2019, qui ne régit plus le renseignement militaire aux fins du maintien de la paix dans aucune mission"], e:"Le manuel MPKI de 2025 (approuvé en mai 2025) et le manuel PKISR sont les dernières versions trouvées, sous la Politique de 2019. Vérifiez toujours l’existence de versions plus récentes."}},
 {m:"m12", a:3,
  en:{q:"A MINUKA trainer notices that a training package’s reference list still cites the 2019 MPKI Handbook. What should the trainer do?", o:["Teach from the 2019 edition","Ignore all training packages","Treat the package as authoritative over the handbooks, since training packages always override doctrine documents","Use the 2025 editions and note the stale reference"], e:"The Resource Hub PKISR training package still lists the superseded 2019.05 MPKI Handbook and 2020.15 PKISR Staff Handbook. Teach from the current editions and point out the gap."},
  bn:{q:"মিনুকার একজন প্রশিক্ষক লক্ষ করলেন, একটি প্রশিক্ষণ প্যাকেজের রেফারেন্স তালিকায় এখনও ২০১৯ সালের MPKI হ্যান্ডবুক উল্লেখ আছে। প্রশিক্ষকের কী করা উচিত?", o:["২০১৯ সংস্করণ থেকে পড়ান","সব প্রশিক্ষণ প্যাকেজ উপেক্ষা করুন","প্যাকেজটিকে হ্যান্ডবুকের চেয়ে বেশি কর্তৃত্বপূর্ণ ধরুন, কারণ প্রশিক্ষণ প্যাকেজ সবসময় ডকট্রিন দলিলের ওপর প্রাধান্য পায়","২০২৫ সংস্করণ ব্যবহার করুন এবং পুরোনো রেফারেন্সটি উল্লেখ করুন"], e:"রিসোর্স হাবের PKISR প্রশিক্ষণ প্যাকেজে এখনও বাতিল হওয়া 2019.05 MPKI হ্যান্ডবুক ও 2020.15 PKISR স্টাফ হ্যান্ডবুক তালিকাভুক্ত। বর্তমান সংস্করণ থেকে পড়ান এবং ঘাটতিটি দেখিয়ে দিন।"},
  fr:{q:"Un formateur de la MINUKA remarque que la liste de références d’un module de formation cite encore le manuel MPKI de 2019. Que doit-il faire ?", o:["Enseigner à partir de l’édition de 2019","Ignorer tous les modules de formation","Considérer le module comme faisant autorité sur les manuels, car les modules de formation priment toujours sur la doctrine","Utiliser les éditions de 2025 et signaler la référence périmée"], e:"Le module PKISR du Resource Hub cite encore le manuel MPKI 2019.05 et le manuel PKISR 2020.15, tous deux remplacés. Enseignez à partir des éditions actuelles et signalez l’écart."}}
];
